  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 07 owner cannot change school status [' || sqlerrm || ']';
  end;

  -- 08 owner invites an admin; claim code + invited_by filled in
