  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08g teachers can''t copy assignments or check readiness [' || sqlerrm || ']';
  end;

  -- ── Bisi: optional French in JSS 1A → only S1 ──────────────
  execute 'reset role';
