  execute 'set local role authenticated';
  select (select count(*) from public.subjects) + (select count(*) from public.teaching_assignments) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 15 other school sees none of School A''s subjects [' || v_n || ']';

  -- ── owner: deletes, then a new session ─────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    delete from public.subjects where id = v_maths;
    v_log := v_log || E'\nFAIL 16a taught subject deleted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23503' then 'PASS' else 'FAIL' end || ' 16a a subject with assignments can''t be deleted [' || sqlerrm || ']';
  end;
  -- Data Processing is on SS 1A and SS 1 Arts but taught by nobody: 96 links → 94
  delete from public.subjects where id = v_dataproc;
  select count(*) into v_n from public.arm_subjects where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_n = 94 then 'PASS' else 'FAIL' end || ' 16b untaught subject deleted with its curriculum links [' || v_n || ' left]';

  -- 16c copy assignments into 2027/2028: Bisi has exited, so only Ada's Maths + Chuka's class
  --     copy across; a second run copies nothing; readiness for 2027/2028 reflects it
  update public.staff set status = 'exited' where id = v_bisi;
  select * into v_r from public.copy_assignments_forward(v_sess1, v_sess2);
  v_ok := v_r.class_teachers_copied = 1 and v_r.subject_teachers_copied = 1;
  select * into v_r from public.copy_assignments_forward(v_sess1, v_sess2);
  v_ok := v_ok and v_r.class_teachers_copied = 0 and v_r.subject_teachers_copied = 0
      and exists (select 1 from public.teaching_assignments where session_id = v_sess2 and arm_id = v_jss1a and subject_id = v_maths and staff_id = v_ada)
      and exists (select 1 from public.class_teachers where session_id = v_sess2 and arm_id = v_jss1b and staff_id = v_chuka and is_lead)
      and not exists (select 1 from public.teaching_assignments where session_id = v_sess2 and staff_id = v_bisi);
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 16c copy_assignments_forward copies once, skips exited staff';
  select * into v_r from public.session_readiness(v_sess2);
  v_log := v_log || E'\n' || case when v_r.terms = 0 and v_r.students_placed = 0 and v_r.active_students_not_placed = 4
        then 'PASS' else 'FAIL' end || ' 16d readiness flags an unprepared session [' || v_r.terms || ' terms, ' || v_r.active_students_not_placed || ' not placed]';

  -- 17 after the school moves to 2027/2028, Ada becomes a PAST teacher of S1 and S2:
  --    she still sees their profiles (names, for old scores), but no longer their
  --    private details or parents
  perform public.set_current_session(v_sess2);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_ada","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 17a past teacher still sees former students'' profiles [' || v_n || ']';
  select (select count(*) from public.student_private_details) + (select count(*) from public.parents) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 17b but not their private details or parents [' || v_n || ']';
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_dele","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 17c a teacher who never taught them sees nobody [' || v_n || ']';

  -- 18 platform admin reads every school's subjects
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  -- only the test schools: real schools in the database don't affect the result
  select count(*) into v_n from public.subjects s where s.organization_id in (v_org, v_org2);
  v_log := v_log || E'\n' || case when v_n = 40 then 'PASS' else 'FAIL' end || ' 18 platform admin reads subjects in every school [' || v_n || ']';

  -- 19 anon has no access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform count(*) from public.subjects;
    v_log := v_log || E'\nFAIL 19 anon read subjects';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 19 anon cannot read subjects [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('04_subjects', v_log);
end;
$test$;

-- ── 05_grading_setup_access_test.sql ──
do $test$
declare
  v_log  text := '';
  v_n    int;
  v_ok   boolean;
  v_txt  text;
  v_org  uuid;  v_claim  text;
  v_org2 uuid;  v_claim2 text;
  v_nursery uuid; v_secondary uuid;
  v_nur1a uuid; v_pry1a uuid; v_jss1a uuid;
  v_teacher uuid; v_t_code text;
  v_s1 uuid; v_p1 uuid; v_p_code text;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup ──────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('School A', 'SCA') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('School B', 'SCB') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bimbo', 'Owner');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  perform public.create_standard_structure(v_org);
  select id into v_nursery   from public.sections where organization_id = v_org and name = 'Nursery';
  select id into v_secondary from public.sections where organization_id = v_org and name = 'Secondary';
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'Nursery 1' returning id into v_nur1a;
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'Primary 1' returning id into v_pry1a;
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'JSS 1' returning id into v_jss1a;

  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Teacher') returning id into v_teacher;
  v_t_code := public.invite_staff(v_teacher);
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Chidi', 'Pupil') returning id into v_s1;
  insert into public.parents (organization_id, first_name, last_name, phone) values (v_org, 'Ngozi', 'Pupil', '0801111111') returning id into v_p1;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact) values (v_org, v_s1, v_p1, 'mother', true);
  v_p_code := public.invite_parent(v_p1);

  -- 00a standard setup: the school's columns + A–F, Secondary's own WAEC boundaries only
  perform public.create_standard_grading(v_org);
  v_ok := (select count(*) from public.score_columns    where organization_id = v_org and section_id is null) = 3
      and (select sum(max_score) from public.score_columns where organization_id = v_org and section_id is null) = 100
      and (select count(*) from public.grade_boundaries where organization_id = v_org and section_id is null) = 6
      and (select count(*) from public.score_columns    where section_id = v_secondary) = 0
      and (select count(*) from public.grade_boundaries where section_id = v_secondary) = 9
      and (select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int, ',' order by min_percent desc)
             from public.grade_boundaries where organization_id = v_org and section_id is null)
          = 'A 70-100,B 60-69,C 50-59,D 45-49,E 40-44,F 0-39';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 00a standard grading setup created';

  -- 00b only for a new school
  begin
    perform public.create_standard_grading(v_org);
    v_log := v_log || E'\nFAIL 00b standard grading created twice';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%already has a grading setup%' then 'PASS' else 'FAIL' end || ' 00b standard setup only for a new school [' || sqlerrm || ']';
  end;

  -- 01 fall-back: JSS 1A uses the school's columns but Secondary's grade boundaries;
  --    Primary 1A uses the school's for both
  select string_agg(name, ',' order by sort_order) into v_txt from public.score_columns_for_arm(v_jss1a);
  v_ok := v_txt = 'CA 1,CA 2,Exam'
      and (select count(*) from public.grade_boundaries_for_arm(v_jss1a)) = 9
      and (select count(*) from public.grade_boundaries_for_arm(v_pry1a)) = 6;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 01 columns and boundaries each fall back to the school''s';

  -- 02 grades come from the ranges; a percentage is rounded half-up first (migration 34)
  v_txt := (public.grade_for(v_jss1a, 74.4)).grade || ',' || (public.grade_for(v_jss1a, 74.5)).grade || ','
        || (public.grade_for(v_jss1a, 39.49)).grade || ',' || (public.grade_for(v_pry1a, 69.99)).grade || ','
        || (public.grade_for(v_pry1a, 0)).grade || ',' || (public.grade_for(v_pry1a, 100)).grade;
  v_log := v_log || E'\n' || case when v_txt = 'B2,A1,F9,A,F,A' then 'PASS' else 'FAIL' end || ' 02 grades come from the ranges, rounded first [' || coalesce(v_txt, 'null') || ']';
  v_ok := not (public.grade_for(v_jss1a, 30)).is_pass and (public.grade_for(v_jss1a, 45)).is_pass;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 02b pass/fail flag comes with the grade';

  -- 03 Nursery gets its own single column; it still uses the school's grade boundaries
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'Observation', 100);
  select string_agg(name, ',') into v_txt from public.score_columns_for_arm(v_nur1a);
  v_ok := v_txt = 'Observation'
      and (public.grade_for(v_nur1a, 72)).grade = 'A'
      and cardinality(public.grading_problems(v_org, v_nursery)) = 0
      and cardinality(public.grading_problems(v_org)) = 0
      and cardinality(public.grading_problems(v_org2)) = 2;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 a section can override just its columns; problems reported for an unset school';

  -- 04 uniqueness is per set (the school's, or one section's)
  begin
    insert into public.score_columns (organization_id, name, max_score) values (v_org, 'ca 1', 10);
    v_log := v_log || E'\nFAIL 04a duplicate column in the school''s set accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 04a column names unique within a set [' || sqlerrm || ']';
  end;
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'CA 1', 10);
  v_log := v_log || E'\nPASS 04b the same column name is fine in another set (Nursery CA 1)';
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent) values (v_org, v_secondary, 'X', 75, 100);
    v_log := v_log || E'\nFAIL 04c owner inserted a grade row directly';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04c grade rows can''t be written directly, even by the owner (migration 34) [' || sqlerrm || ']';
  end;

  -- 05 validation
  begin
    perform public.set_grade_scale(v_org, null, '[{"grade":"A","min_percent":0,"max_percent":101,"remark":null,"is_pass":true}]'::jsonb);
    v_log := v_log || E'\nFAIL 05a grade ending above 100% accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%whole numbers from 0 to 100%' then 'PASS' else 'FAIL' end || ' 05a grades end at 100% at most [' || sqlerrm || ']';
  end;
  begin
    insert into public.score_columns (organization_id, name, max_score) values (v_org, 'Project', 0);
    v_log := v_log || E'\nFAIL 05b zero max score accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 05b max score must be positive [' || sqlerrm || ']';
  end;
  insert into public.score_columns (organization_id, name, max_score, sort_order) values (v_org, 'Project', 12.5, 4);
  v_log := v_log || E'\nPASS 05c decimal max scores allowed (12.5)';

  -- ── teacher: reads the setup, can't change it ──────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_t_code);
  select count(*) into v_n from public.score_columns;
  v_log := v_log || E'\n' || case when v_n = 6 then 'PASS' else 'FAIL' end || ' 06a teacher reads the grading setup [' || v_n || ' score columns]';
  begin
    insert into public.score_columns (organization_id, name, max_score) values (v_org, 'Quiz', 5);
    v_log := v_log || E'\nFAIL 06b teacher added a score column';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06b teachers can''t change the setup [' || sqlerrm || ']';
  end;
  begin
    update public.grade_boundaries set min_percent = 50 where organization_id = v_org and section_id is null and grade = 'A';
    v_log := v_log || E'\nFAIL 06c teacher update on grade boundaries accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06c teachers can''t edit grade boundaries [' || sqlerrm || ']';
  end;
  begin
    perform public.create_standard_grading(v_org2);
    v_log := v_log || E'\nFAIL 06d teacher set up another school';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06d teachers can''t run the standard setup [' || sqlerrm || ']';
  end;

  -- ── parent: reads grade boundaries (for the report card) ─
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_p_code);
  select count(*) into v_n from public.grade_boundaries;
  v_log := v_log || E'\n' || case when v_n = 15 then 'PASS' else 'FAIL' end || ' 07 parent reads grade boundaries [' || v_n || ']';

  -- ── other school ───────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select (select count(*) from public.score_columns) + (select count(*) from public.grade_boundaries) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 08 other school sees none of School A''s setup [' || v_n || ']';

  -- ── owner: removing Secondary's boundaries falls back to the school's ─
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.remove_section_grade_scale(v_org, v_secondary);
  v_ok := (public.grade_for(v_jss1a, 74.5)).grade = 'A'
      and (select count(*) from public.grade_boundaries_for_arm(v_jss1a)) = 6;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 09 without its own boundaries, Secondary uses the school''s';

  -- 10 anon has no access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform count(*) from public.grade_boundaries;
    v_log := v_log || E'\nFAIL 10 anon read grade boundaries';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 10 anon cannot read grade boundaries [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('05_grading_setup', v_log);
end;
$test$;

-- ── 06_owner_staff_record_test.sql ──
do $test$
declare
  v_log    text := '';
  v_n      int;
  v_org    uuid;
  v_claim  text;
  v_member public.organization_members;
  v_staff  public.staff;
  v_ada    uuid;
  v_t_code text;
  v_owner2_code text;
  v_owner3_code text;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: one school ──────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim from public.create_organization('Test School', 'TST') c;

  -- 01 an owner code needs a first and last name; blanks don't count
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.redeem_claim_code(v_claim);
    v_log := v_log || E'\nFAIL 01a owner redeemed without a name';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 01a owner code needs a name [' || sqlerrm || ']';
  end;
  begin
    perform public.redeem_claim_code(v_claim, '  ', 'Owner');
    v_log := v_log || E'\nFAIL 01b owner redeemed with a blank first name';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 01b blank name rejected [' || sqlerrm || ']';
  end;

  -- 02 the same code still works once a name is given; the staff record is linked
  v_member := public.redeem_claim_code(v_claim, ' Olu ', ' Owner ', 'olu@school.test', '0801234567');
  select s.* into v_staff from public.staff s where s.member_id = v_member.id;
  v_log := v_log || E'\n' || case when v_member.status = 'active' and v_member.role = 'owner'
        and v_staff.first_name = 'Olu' and v_staff.last_name = 'Owner'
        and v_staff.email = 'olu@school.test' and v_staff.phone = '0801234567'
        and v_staff.job_title = 'Owner' and v_staff.staff_type = 'non_teaching'
        and v_staff.staff_number = 'TST/STF/0001'
        then 'PASS' else 'FAIL' end || ' 02 owner redeems and gets a linked staff record [' || coalesce(v_staff.staff_number, 'none') || ']';

  -- 03 the record has its private details row, like every staff member
  select count(*) into v_n from public.staff_private_details where staff_id = v_staff.id;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 03 owner''s private details row created [' || v_n || ']';

  -- 04 the owner edits their own record like any other
  perform public.update_staff(v_staff.id, 'Olu', 'Owner', null, '', null, '0801234567', 'olu@school.test', null, null,
                              'Proprietor', 'teaching', 'active', null, null, null, null, null, null);
  select count(*) into v_n from public.staff s
    where s.id = v_staff.id and s.job_title = 'Proprietor' and s.staff_type = 'teaching' and s.staff_number = 'TST/STF/0001';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 04 owner can edit own staff record';

  -- 05 a used owner code is still rejected, name or not (returns NULL since migration 13)
  begin
    v_member := public.redeem_claim_code(v_claim, 'Olu', 'Owner');
    v_log := v_log || E'\n' || case when v_member.id is null then 'PASS' else 'FAIL' end || ' 05 used owner code rejected';
  exception when others then
    v_log := v_log || E'\nFAIL 05 used owner code raised instead of returning NULL [' || sqlerrm || ']';
  end;

  -- 06 a teacher code needs no name and makes no extra staff record
  v_ada := (public.create_staff(p_organization_id => v_org, p_first_name => 'Ada', p_last_name => 'Teacher')).id;
  v_t_code := public.invite_staff(v_ada);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_t_code);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_member.role = 'teacher' and v_member.status = 'active' and v_n = 2
        then 'PASS' else 'FAIL' end || ' 06 teacher code needs no name, no extra staff record [' || v_n || ' staff]';

  -- 07 a second owner who is already on staff keeps their one record
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  insert into public.organization_members (organization_id, role) values (v_org, 'owner') returning claim_code into v_owner2_code;
  insert into public.organization_members (organization_id, role) values (v_org, 'owner') returning claim_code into v_owner3_code;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_owner2_code);
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_member.role = 'owner' and v_n = 2
        then 'PASS' else 'FAIL' end || ' 07 existing staff member becomes owner without a second record [' || v_n || ' staff]';

  -- 08 a second owner who is new to the school gets their own record
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_2","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_owner3_code, 'Bimbo', 'Partner');
  select s.* into v_staff from public.staff s where s.member_id = v_member.id;
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_n = 3 and v_staff.last_name = 'Partner' and v_staff.staff_number = 'TST/STF/0003'
        then 'PASS' else 'FAIL' end || ' 08 new co-owner gets own staff record [' || v_n || ' staff, ' || coalesce(v_staff.staff_number, 'none') || ']';

  -- 09 anon cannot redeem
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform public.redeem_claim_code('ABCD2345', 'Anon', 'User');
    v_log := v_log || E'\nFAIL 09 anon called redeem_claim_code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 09 anon cannot redeem [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('06_owner_staff_record_test', v_log);
end;
$test$;

-- ── 07_platform_join_code_access_test.sql ──
do $test$
declare
  v_log    text := '';
  v_n      int;
  v_code   text;
  v_code2  text;
  v_hint   text;
  v_admin  public.platform_admins;
  v_s      record;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- any real team code is set aside inside this test, so the checks start clean
  delete from private.platform_join_code;

  -- 01 with no code yet, status says so and a join returns null
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_s from public.platform_join_code_status();
  v_log := v_log || E'\n' || case when v_s.has_code = false and v_s.is_enabled = false and v_s.code_hint is null
        then 'PASS' else 'FAIL' end || ' 01a status with no code yet';
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_join_code('ABCD-EFGH-2345', 'New Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id is null then 'PASS' else 'FAIL' end || ' 01b no code yet → null';

  -- 02 an admin creates the code: 12 allowed characters, only the hash stored
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select r.code, r.code_hint into v_code, v_hint from public.rotate_platform_join_code() r;
  execute 'reset role';
  select count(*) into v_n from private.platform_join_code c
    where c.code_hash = private.platform_code_hash(v_code) and c.code_hash <> v_code
      and c.code_hint = right(v_code, 4) and c.is_enabled and c.changed_by = 'user_dummy_platform_admin';
  v_log := v_log || E'\n' || case when v_code ~ '^[A-HJ-NP-Z2-9]{12}$' and v_hint = right(v_code, 4) and v_n = 1
        then 'PASS' else 'FAIL' end || ' 02 code shape, hash stored not the code';

  -- 03 status shows the live code to an admin
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_s from public.platform_join_code_status();
  v_log := v_log || E'\n' || case when v_s.has_code and v_s.is_enabled and v_s.code_hint = v_hint
        and v_s.changed_by_name = 'Dummy Platform Admin' then 'PASS' else 'FAIL' end || ' 03 status shows hint and who changed it';

  -- 04 a non-admin can't rotate, switch, or see the status
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.rotate_platform_join_code();
    v_log := v_log || E'\nFAIL 04a non-admin rotated the code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04a non-admin cannot rotate [' || sqlerrm || ']';
  end;
  begin
    perform public.set_platform_join_enabled(false);
    v_log := v_log || E'\nFAIL 04b non-admin switched the code off';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04b non-admin cannot switch [' || sqlerrm || ']';
  end;
  begin
    perform public.platform_join_code_status();
    v_log := v_log || E'\nFAIL 04c non-admin read the status';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04c non-admin cannot see status [' || sqlerrm || ']';
  end;

  -- 05 clients can't read the code table directly
  begin
    select count(*) into v_n from private.platform_join_code;
    v_log := v_log || E'\nFAIL 05 authenticated read private.platform_join_code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 05 code table not readable [' || sqlerrm || ']';
  end;

  -- 06 a name is required
  begin
    perform public.redeem_platform_join_code(v_code, '   ');
    v_log := v_log || E'\nFAIL 06 joined without a name';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 06 name required [' || sqlerrm || ']';
  end;

  -- 07 a wrong code returns null and makes no admin
  v_admin := public.redeem_platform_join_code('WRONG-CODE-0000', 'New Person');
  execute 'reset role';
  select count(*) into v_n from public.platform_admins where clerk_user_id = 'test_newcomer';
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id is null and v_n = 0
        then 'PASS' else 'FAIL' end || ' 07 wrong code → null, no admin made';

  -- 08 the right code, typed loosely, makes the caller an active admin
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_join_code(
    lower(substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4) || ' ' || substr(v_code, 9, 4)),
    ' New Person ', ' new@hamrash.test ');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'test_newcomer' and v_admin.is_active
        and v_admin.full_name = 'New Person' and v_admin.email = 'new@hamrash.test' and v_admin.joined_at is not null
        then 'PASS' else 'FAIL' end || ' 08 code accepted, caller is an admin with joined_at';
  select count(*) into v_n from public.organizations;  -- reads all schools without error
  v_log := v_log || E'\n' || case when private.is_platform_admin() then 'PASS' else 'FAIL' end || ' 08b newcomer passes the platform-admin check';

  -- 09 the code is reusable: a second person joins with the same code
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_other","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_join_code(v_code, 'Other Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'test_other' and v_admin.is_active
        then 'PASS' else 'FAIL' end || ' 09 same code works for a second person';

  -- 10 an existing admin redeeming just gets their row back
  v_admin := public.redeem_platform_join_code('NOT-THE-CODE', 'Other Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'test_other'
        then 'PASS' else 'FAIL' end || ' 10 existing admin gets their row back';

  -- 11 rotating stops the old code and starts a new one
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select r.code into v_code2 from public.rotate_platform_join_code() r;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_third","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_join_code(v_code, 'Third Person');
  v_log := v_log || E'\n' || case when v_code2 <> v_code and v_admin.clerk_user_id is null
        then 'PASS' else 'FAIL' end || ' 11a old code rejected after rotating';
  v_admin := public.redeem_platform_join_code(v_code2, 'Third Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'test_third'
        then 'PASS' else 'FAIL' end || ' 11b new code accepted';

  -- 12 switched off: the code is refused; switched on: it works again
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_platform_join_enabled(false);
  select * into v_s from public.platform_join_code_status();
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_fourth","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_join_code(v_code2, 'Fourth Person');
  v_log := v_log || E'\n' || case when v_s.is_enabled = false and v_admin.clerk_user_id is null
        then 'PASS' else 'FAIL' end || ' 12a switched-off code rejected';
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_platform_join_enabled(true);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_fourth","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_join_code(v_code2, 'Fourth Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'test_fourth'
        then 'PASS' else 'FAIL' end || ' 12b switched back on, code works';

  -- 13 rotating while switched off turns joining back on
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_platform_join_enabled(false);
  perform public.rotate_platform_join_code();
  select * into v_s from public.platform_join_code_status();
  v_log := v_log || E'\n' || case when v_s.is_enabled then 'PASS' else 'FAIL' end || ' 13 rotating switches joining on';

  -- 14 a turned-off admin can't use the code to get back in
  execute 'reset role';
  update public.platform_admins set is_active = false where clerk_user_id = 'test_newcomer';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.redeem_platform_join_code('ANYTHING', 'New Person');
    v_log := v_log || E'\nFAIL 14 turned-off admin rejoined';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 14 turned-off admin refused [' || sqlerrm || ']';
  end;

  -- 15 anon can't join
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform public.redeem_platform_join_code('ABCD-EFGH-2345', 'Anon');
    v_log := v_log || E'\nFAIL 15 anon called redeem_platform_join_code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 15 anon cannot join [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('07_platform_join_code', v_log);
end;
$test$;

-- ── 08_check_claim_code_test.sql ──
do $test$
declare
  v_log         text := '';
  v_n           int;
  v_org         uuid;
  v_org2        uuid;
  v_owner_claim text;
  v_claim2      text;
  v_ada         uuid;
  v_pat         uuid;
  v_pam         uuid;
  v_t_code      text;
  v_p_code      text;
  v_pam_code    text;
  v_r           record;
  v_member      public.organization_members;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: two schools ─────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_owner_claim from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  -- 01 an owner code checks as ok, for the admin app, and needs a name; nothing is used up
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_r from public.check_claim_code(v_owner_claim);
  v_log := v_log || E'\n' || case when v_r.status = 'ok' and v_r.organization_id = v_org and v_r.school_name = 'Test School'
        and v_r.role = 'owner' and v_r.app = 'admin' and v_r.needs_name
        then 'PASS' else 'FAIL' end || ' 01a owner code checks ok [' || coalesce(v_r.status, 'null') || ']';
  execute 'reset role';
  select count(*) into v_n from public.organization_members m where m.claim_code = v_owner_claim and m.status = 'invited';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 01b checking does not use the code';

  -- the owner joins and invites a teacher and a principal
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_owner_claim, 'Olu', 'Owner');
  insert into public.staff (organization_id, first_name, last_name, job_title)
    values (v_org, 'Ada', 'Teacher', 'Maths Teacher') returning id into v_ada;
  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Pat', 'Principal', 'Principal', 'non_teaching') returning id into v_pat;
  v_t_code := public.invite_staff(v_ada, 'teacher');
  v_p_code := public.invite_staff(v_pat, 'principal');

  -- 02 a principal code (lowercase, with a dash) is for the admin app and needs no name
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_r from public.check_claim_code(lower(substr(v_p_code, 1, 4) || '-' || substr(v_p_code, 5, 4)));
  v_log := v_log || E'\n' || case when v_r.status = 'ok' and v_r.role = 'principal' and v_r.app = 'admin' and not v_r.needs_name
        then 'PASS' else 'FAIL' end || ' 02 principal code checks ok for the admin app [' || coalesce(v_r.app, 'null') || ']';

  -- 03 a teacher code says app = staff and stays unused
  select * into v_r from public.check_claim_code(v_t_code);
  execute 'reset role';
  select count(*) into v_n from public.organization_members m where m.claim_code = v_t_code and m.status = 'invited';
  v_log := v_log || E'\n' || case when v_r.status = 'ok' and v_r.role = 'teacher' and v_r.app = 'staff' and v_n = 1
        then 'PASS' else 'FAIL' end || ' 03 teacher code is for the staff app and stays unused [' || coalesce(v_r.app, 'null') || ']';

  -- 04 a half-typed code is not found
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_r from public.check_claim_code('KQ7');
  v_log := v_log || E'\n' || case when v_r.status = 'not_found' and v_r.school_name is null
        then 'PASS' else 'FAIL' end || ' 04 malformed code not found [' || v_r.status || ']';

  -- 05 a wrong code is just not found
  select * into v_r from public.check_claim_code('ZZZZ-ZZZZ');
  v_log := v_log || E'\n' || case when v_r.status = 'not_found' and v_r.school_name is null
        then 'PASS' else 'FAIL' end || ' 05 wrong code not found [' || v_r.status || ']';

  -- 06 redeeming a wrong code returns NULL (no error)
  v_member := public.redeem_claim_code('ZZZZ-ZZZY');
  v_log := v_log || E'\n' || case when v_member.id is null
        then 'PASS' else 'FAIL' end || ' 06 wrong redeem returns NULL';

  -- 07 many wrong codes in a row never lock the account out
  for i in 1..8 loop
    perform public.check_claim_code('ZZZZ-ZZ' || lpad(i::text, 2, '0'));
  end loop;
  select * into v_r from public.check_claim_code(v_p_code);
  v_log := v_log || E'\n' || case when v_r.status = 'ok' and v_r.role = 'principal'
        then 'PASS' else 'FAIL' end || ' 07 no lockout after 8 wrong codes [' || v_r.status || ']';

  -- 12 redeeming works after wrong tries
  v_member := public.redeem_claim_code(v_p_code);
  execute 'reset role';
  v_log := v_log || E'\n' || case when v_member.role = 'principal' and v_member.status = 'active'
        then 'PASS' else 'FAIL' end || ' 12 redeem works after wrong tries';

  -- 13 a second principal code at the same school says already_member
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Pam', 'Principal', 'Principal', 'non_teaching') returning id into v_pam;
  v_pam_code := public.invite_staff(v_pam, 'principal');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_r from public.check_claim_code(v_pam_code);
  v_log := v_log || E'\n' || case when v_r.status = 'already_member' and v_r.school_name = 'Test School'
        then 'PASS' else 'FAIL' end || ' 13 same role twice says already_member [' || coalesce(v_r.status, 'null') || ']';

  -- 14 a suspended school's code says school_inactive
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_organization_status(v_org2, 'suspended');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select * into v_r from public.check_claim_code(v_claim2);
  v_log := v_log || E'\n' || case when v_r.status = 'school_inactive' and v_r.school_name = 'Other School'
        then 'PASS' else 'FAIL' end || ' 14 suspended school says school_inactive [' || coalesce(v_r.status, 'null') || ']';

  -- 16 anon can't check a code
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform public.check_claim_code('ABCD-2345');
    v_log := v_log || E'\nFAIL 16 anon called check_claim_code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16 anon cannot check [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('08_check_claim_code_test', v_log);
end;
$test$;

-- ── 09_owner_edits_school_leaders_invite_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_admin_claim     text;
  v_principal_claim text;
  v_vp_claim        text;
  v_extra_claim     text;
  v_admin_invite    text;
  v_member public.organization_members;
  v_n      int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- Setup: a school with an owner, an admin, a principal and a VP
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'admin')
    returning claim_code into v_admin_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'vice_principal')
    returning claim_code into v_vp_claim;

  -- 01 owner edits school details
  update public.organizations set name = 'Renamed School' where id = v_org;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 01 owner can edit school details';

  -- 02 admin cannot edit school details
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_admin_claim);
  update public.organizations set name = 'Admin Was Here' where id = v_org;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 02 admin cannot edit school details [' || v_n || ' rows]';

  -- 03 admin still invites any role except owner
  insert into public.organization_members (organization_id, role) values (v_org, 'admin')
    returning claim_code into v_admin_invite;
  v_log := v_log || E'\n' || case when v_admin_invite is not null then 'PASS' else 'FAIL' end || ' 03 admin can still invite an admin';

  -- 04 principal cannot edit school details
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  update public.organizations set name = 'Principal Was Here' where id = v_org;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 04 principal cannot edit school details [' || v_n || ' rows]';

  -- 05 principal invites principal, VP, bursar, teacher and staff
  begin
    insert into public.organization_members (organization_id, role) values
      (v_org, 'principal'), (v_org, 'vice_principal'), (v_org, 'bursar'), (v_org, 'teacher'), (v_org, 'staff');
    v_log := v_log || E'\nPASS 05 principal invites principal, VP, bursar, teacher, staff';
  exception when others then
    v_log := v_log || E'\nFAIL 05 principal could not invite up to their level [' || sqlerrm || ']';
  end;

  -- 06 principal cannot invite an admin
  begin
    insert into public.organization_members (organization_id, role) values (v_org, 'admin');
    v_log := v_log || E'\nFAIL 06 principal invited an admin';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06 principal cannot invite an admin [' || sqlerrm || ']';
  end;

  -- 07 principal cannot invite an owner
  begin
    insert into public.organization_members (organization_id, role) values (v_org, 'owner');
    v_log := v_log || E'\nFAIL 07 principal invited an owner';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 07 principal cannot invite an owner [' || sqlerrm || ']';
  end;

  -- 08 principal cancels an unclaimed teacher invite
  insert into public.organization_members (organization_id, role) values (v_org, 'teacher')
    returning claim_code into v_extra_claim;
  delete from public.organization_members where claim_code = v_extra_claim;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 08 principal cancels an unclaimed teacher invite';

  -- 09 principal cannot cancel an unclaimed admin invite
  delete from public.organization_members where claim_code = v_admin_invite;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 09 principal cannot cancel an admin invite [' || v_n || ' rows]';

  -- 10 principal cannot change anyone's role
  update public.organization_members set role = 'admin' where clerk_user_id = 'test_principal';
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 10 principal cannot change roles [' || v_n || ' rows]';

  -- 11 VP invites a bursar but not an admin
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_vp","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_vp_claim);
  begin
    insert into public.organization_members (organization_id, role) values (v_org, 'bursar');
    v_log := v_log || E'\nPASS 11a VP invites a bursar';
  exception when others then
    v_log := v_log || E'\nFAIL 11a VP could not invite a bursar [' || sqlerrm || ']';
  end;
  begin
    insert into public.organization_members (organization_id, role) values (v_org, 'admin');
    v_log := v_log || E'\nFAIL 11b VP invited an admin';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 11b VP cannot invite an admin [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('09_owner_edits_school_leaders_invite_test', v_log);
end;
$test$;

-- ── 10_leaders_delete_sessions_and_terms_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_principal_claim text;
  v_vp_claim        text;
  v_bursar_claim    text;
  v_session  uuid;
  v_session2 uuid;
  v_term     uuid;
  v_term2    uuid;
  v_n      int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- Setup: a school with an owner, a principal, a VP and a bursar
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'vice_principal')
    returning claim_code into v_vp_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')
    returning claim_code into v_bursar_claim;

  -- Principal adds two sessions, each with a term
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/27', '2026-09-07', '2027-07-16') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First term', 1, '2026-09-07', '2026-12-11') returning id into v_term;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2027/28', '2027-09-06', '2028-07-14') returning id into v_session2;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session2, 'First term', 1, '2027-09-06', '2027-12-10') returning id into v_term2;

  -- 01 bursar cannot delete a term
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);
  delete from public.academic_terms where id = v_term;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 01 bursar cannot delete a term [' || v_n || ' rows]';

  -- 02 principal deletes a term
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  delete from public.academic_terms where id = v_term;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 02 principal deletes a term';

  -- 03 principal deletes the now-empty session
  delete from public.academic_sessions where id = v_session;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 03 principal deletes an empty session';

  -- 04 a session with terms still can't be deleted
  begin
    delete from public.academic_sessions where id = v_session2;
    v_log := v_log || E'\nFAIL 04 deleted a session that still has terms';
  exception when foreign_key_violation then
    v_log := v_log || E'\nPASS 04 a session with terms is kept [' || sqlerrm || ']';
  end;

  -- 05 VP deletes a term, then its session
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_vp","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_vp_claim);
  delete from public.academic_terms where id = v_term2;
  delete from public.academic_sessions where id = v_session2;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 05 VP deletes a term and its session';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('10_leaders_delete_sessions_and_terms_test', v_log);
end;
$test$;

-- ── 11_close_sessions_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_principal_claim text;
  v_old    uuid;   -- 2025/26, ended
  v_old_term uuid;
  v_now    uuid;   -- this year, current
  v_now_term uuid;
  v_session public.academic_sessions;
  v_usage  record;
  v_n      int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- Setup: a school with an owner and a principal
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;

  -- Principal builds last year (ended) and this year (current)
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2024/25', '2024-09-09', '2025-07-18') returning id into v_old;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_old, 'First term', 1, '2024-09-09', '2024-12-13') returning id into v_old_term;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, 'Next year', current_date - 30, current_date + 300) returning id into v_now;
  perform public.set_current_session(v_old);

  -- 01 session dates can't shrink past one of its terms
  begin
    update public.academic_sessions set starts_on = '2024-10-01' where id = v_old;
    v_log := v_log || E'\nFAIL 01 session dates left a term outside';
  exception when check_violation then
    v_log := v_log || E'\nPASS 01 session dates must still hold every term [' || sqlerrm || ']';
  end;

  -- 02 the current session can't be closed
  begin
    perform public.close_session(v_old);
    v_log := v_log || E'\nFAIL 02 closed the current session';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%current%' then 'PASS' else 'FAIL' end || ' 02 current session can''t be closed [' || sqlerrm || ']';
  end;

  -- 03 a new current session without a current term isn't enough
  perform public.set_current_session(v_now);
  begin
    perform public.close_session(v_old);
    v_log := v_log || E'\nFAIL 03 closed with no current term to take new work';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%current term%' then 'PASS' else 'FAIL' end || ' 03 needs a current term in the new session [' || sqlerrm || ']';
  end;

  -- the new session gets its current term
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_now, 'First term', 1, current_date - 30, current_date + 60) returning id into v_now_term;
  perform public.set_current_term(v_now_term);

  -- 03b the current session itself can't be closed
  begin
    perform public.close_session(v_now);
    v_log := v_log || E'\nFAIL 03b closed the current session';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%current%' or sqlerrm like '%ended%' then 'PASS' else 'FAIL' end || ' 03b the current session can''t be closed [' || sqlerrm || ']';
  end;

  -- 04 principal closes last year once the new session and term are current
  v_session := public.close_session(v_old);
  v_log := v_log || E'\n' || case when v_session.closed_at is not null and v_session.closed_by = 'test_principal' then 'PASS' else 'FAIL' end || ' 04 principal closes an ended session';

  -- 05 a closed session can't be renamed
  begin
    update public.academic_sessions set name = 'Renamed' where id = v_old;
    v_log := v_log || E'\nFAIL 05 renamed a closed session';
  exception when others then
    v_log := v_log || E'\nPASS 05 closed session can''t be renamed [' || sqlerrm || ']';
  end;

  -- 06 a closed session's terms can't be added, edited or removed
  begin
    insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
      values (v_org, v_old, 'Second term', 2, '2025-01-06', '2025-04-04');
    v_log := v_log || E'\nFAIL 06a added a term to a closed session';
  exception when others then
    v_log := v_log || E'\nPASS 06a no new terms in a closed session [' || sqlerrm || ']';
  end;
  begin
    update public.academic_terms set name = 'Renamed' where id = v_old_term;
    v_log := v_log || E'\nFAIL 06b edited a closed session''s term';
  exception when others then
    v_log := v_log || E'\nPASS 06b closed session''s terms are read-only [' || sqlerrm || ']';
  end;
  begin
    delete from public.academic_terms where id = v_old_term;
    v_log := v_log || E'\nFAIL 06c removed a closed session''s term';
  exception when others then
    v_log := v_log || E'\nPASS 06c closed session''s terms can''t be removed [' || sqlerrm || ']';
  end;

  -- 07 a closed session can't be deleted
  begin
    delete from public.academic_sessions where id = v_old;
    v_log := v_log || E'\nFAIL 07 deleted a closed session';
  exception when others then
    v_log := v_log || E'\nPASS 07 closed session is kept [' || sqlerrm || ']';
  end;

  -- 08 session_usage counts what a session holds
  select * into v_usage from public.session_usage(v_old);
  v_log := v_log || E'\n' || case when v_usage.terms = 1 and v_usage.placements = 0 then 'PASS' else 'FAIL' end
        || ' 08 session_usage [terms ' || v_usage.terms || ', placements ' || v_usage.placements || ']';

  -- 09 principal can't reopen
  begin
    perform public.reopen_session(v_old);
    v_log := v_log || E'\nFAIL 09 principal reopened a session';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 09 only the owner reopens [' || sqlerrm || ']';
  end;

  -- 10 owner reopens; the session can be edited again
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_session := public.reopen_session(v_old);
  update public.academic_sessions set name = '2024/25 (fixed)' where id = v_old;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_session.closed_at is null and v_n = 1 then 'PASS' else 'FAIL' end || ' 10 owner reopens and can edit again';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('11_close_sessions_test', v_log);
end;
$test$;

-- ── 12_current_term_delete_test.sql ──
do $test$
declare
  v_log text := '';
  v_org uuid;
  v_claim text;
  v_session uuid;
  v_first uuid;
  v_second uuid;
  v_count int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Current Term Test School', 'CTS') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');

  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/27', current_date - 90, current_date + 300)
    returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First term', 1, current_date - 90, current_date - 10)
    returning id into v_first;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'Second term', 2, current_date, current_date + 80)
    returning id into v_second;
  perform public.set_current_term(v_first);

  -- 01 direct DELETE of the current term fails with the intended message.
  begin
    delete from public.academic_terms where id = v_first;
    v_log := v_log || E'\nFAIL 01 deleted the current term';
  exception when others then
    v_log := v_log || E'\n' || case
      when sqlstate = 'P0001' and sqlerrm = 'Make another term current before removing this one'
        then 'PASS' else 'FAIL' end
      || ' 01 current term deletion is refused [' || sqlerrm || ']';
  end;
  select count(*) into v_count from public.academic_terms where id = v_first;
  v_log := v_log || E'\n' || case when v_count = 1 then 'PASS' else 'FAIL' end
    || ' 02 refused deletion keeps the current term';

  -- 03 ordinary non-current term remains deletable.
  delete from public.academic_terms where id = v_second;
  get diagnostics v_count = row_count;
  v_log := v_log || E'\n' || case when v_count = 1 then 'PASS' else 'FAIL' end
    || ' 03 non-current term can be removed';

  -- 04 after making another term current, the former current term can go.
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'Second term', 2, current_date, current_date + 80)
    returning id into v_second;
  perform public.set_current_term(v_second);
  delete from public.academic_terms where id = v_first;
  get diagnostics v_count = row_count;
  v_log := v_log || E'\n' || case when v_count = 1 then 'PASS' else 'FAIL' end
    || ' 04 former current term can be removed after replacement';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('12_current_term_delete_test', v_log);
end;
$test$;

-- ── 13_leaders_delete_structure_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_principal_claim text;
  v_bursar_claim    text;
  v_section uuid;
  v_class   uuid;
  v_arm     uuid;
  v_arm2    uuid;
  v_n      int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')
    returning claim_code into v_bursar_claim;

  -- Principal builds a section, a class and two arms
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  insert into public.sections (organization_id, name) values (v_org, 'Primary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name) values (v_org, v_section, 'Primary 1') returning id into v_class;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_class, 'A') returning id into v_arm;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_class, 'B') returning id into v_arm2;

  -- 01 bursar cannot delete an arm
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);
  delete from public.class_arms where id = v_arm2;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 01 bursar cannot delete an arm [' || v_n || ' rows]';

  -- 02 principal deletes an arm
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  delete from public.class_arms where id = v_arm2;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 02 principal deletes an arm';

  -- 03 a class that still has an arm is kept
  begin
    delete from public.classes where id = v_class;
    v_log := v_log || E'\nFAIL 03 deleted a class that still has arms';
  exception when foreign_key_violation then
    v_log := v_log || E'\nPASS 03 a class with arms is kept [' || sqlerrm || ']';
  end;

  -- 04 a section that still has a class is kept
  begin
    delete from public.sections where id = v_section;
    v_log := v_log || E'\nFAIL 04 deleted a section that still has classes';
  exception when foreign_key_violation then
    v_log := v_log || E'\nPASS 04 a section with classes is kept [' || sqlerrm || ']';
  end;

  -- 05 principal empties and removes the whole structure
  delete from public.class_arms where id = v_arm;
  delete from public.classes where id = v_class;
  delete from public.sections where id = v_section;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 05 principal removes an arm, its class and its section';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('13_leaders_delete_structure_test', v_log);
end;
$test$;

-- ── 14_leaders_delete_subjects_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_principal_claim text;
  v_bursar_claim    text;
  v_section uuid;
  v_class   uuid;
  v_arm     uuid;
  v_session uuid;
  v_term    uuid;
  v_staff   uuid;
  v_maths   uuid;
  v_french  uuid;
  v_latin   uuid;
  v_n      int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  -- Owner sets up an arm, a session, a teacher and three subjects
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')
    returning claim_code into v_bursar_claim;
  insert into public.sections (organization_id, name) values (v_org, 'Secondary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name) values (v_org, v_section, 'JSS 1') returning id into v_class;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_class, 'A') returning id into v_arm;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term;
  perform public.set_current_term(v_term);
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Maths') returning id into v_staff;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Mathematics', 'MTH') returning id into v_maths;
  insert into public.subjects (organization_id, name, code) values (v_org, 'French', 'FRE') returning id into v_french;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Latin', 'LAT') returning id into v_latin;
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm, v_maths);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm, v_french);
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id)
    values (v_org, v_session, v_arm, v_maths, v_staff);

  -- 01 bursar cannot delete a subject
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);
  delete from public.subjects where id = v_latin;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 01 bursar cannot delete a subject [' || v_n || ' rows]';

  -- 02 principal deletes a subject no arm takes
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  delete from public.subjects where id = v_latin;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 02 principal deletes an unused subject';

  -- 03 principal deletes a subject an arm takes; its arm link goes with it
  delete from public.subjects where id = v_french;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1
      and not exists (select 1 from public.arm_subjects where subject_id = v_french)
    then 'PASS' else 'FAIL' end || ' 03 principal deletes a subject only on the curriculum, its arm link goes too';

  -- 04 a subject with a teacher assigned is kept
  begin
    delete from public.subjects where id = v_maths;
    v_log := v_log || E'\nFAIL 04 deleted a subject that is taught';
  exception when foreign_key_violation then
    v_log := v_log || E'\nPASS 04 a taught subject is kept [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('14_leaders_delete_subjects_test', v_log);
end;
$test$;

-- ── 15_class_teachers_keep_their_arm_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_principal_claim text;
  v_section uuid;
  v_class   uuid;
  v_arm     uuid;
  v_session uuid;
  v_term    uuid;
  v_staff   uuid;
  v_n      int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  -- Owner sets up an arm with a class teacher
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.sections (organization_id, name) values (v_org, 'Primary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name) values (v_org, v_section, 'Primary 1') returning id into v_class;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_class, 'A') returning id into v_arm;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term;
  perform public.set_current_term(v_term);
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Class') returning id into v_staff;
  insert into public.class_teachers (organization_id, session_id, arm_id, staff_id) values (v_org, v_session, v_arm, v_staff);

  -- 01 the arm stays while it has a class teacher
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  begin
    delete from public.class_arms where id = v_arm;
    v_log := v_log || E'\nFAIL 01 deleted an arm that has a class teacher';
  exception when foreign_key_violation then
    v_log := v_log || E'\nPASS 01 an arm with a class teacher is kept [' || sqlerrm || ']';
  end;
  select count(*) into v_n from public.class_teachers where arm_id = v_arm;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 02 its class teacher is still assigned';

  -- 03 once unassigned, the arm can go
  delete from public.class_teachers where arm_id = v_arm;
  delete from public.class_arms where id = v_arm;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 03 after unassigning, the principal deletes the arm';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('15_class_teachers_keep_their_arm_test', v_log);
end;
$test$;

-- ── 16_keep_taught_arm_subjects_test.sql ──
do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_claim  text;
  v_principal_claim text;
  v_section uuid;
  v_class   uuid;
  v_arm_a   uuid;
  v_arm_b   uuid;
  v_session uuid;
  v_term    uuid;
  v_staff   uuid;
  v_student uuid;
  v_maths   uuid;
  v_french  uuid;
  v_art     uuid;
  v_n       int;
  v_teacher text;
  v_choices int;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim
    from public.create_organization('Test School', 'TST') c;

  -- Owner sets up JSS 1A (taught Maths, a student who chose French, Art
  -- unused) and JSS 1B (taught Maths, no students)
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.sections (organization_id, name) values (v_org, 'Secondary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name) values (v_org, v_section, 'JSS 1') returning id into v_class;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_class, 'A') returning id into v_arm_a;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_class, 'B') returning id into v_arm_b;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term;
  perform public.set_current_term(v_term);
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Bello') returning id into v_staff;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Mathematics', 'MTH') returning id into v_maths;
  insert into public.subjects (organization_id, name, code) values (v_org, 'French', 'FRE') returning id into v_french;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Art', 'ART') returning id into v_art;
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_a, v_maths);
  insert into public.arm_subjects (organization_id, arm_id, subject_id, is_compulsory) values (v_org, v_arm_a, v_french, false);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_a, v_art);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_b, v_maths);
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id)
    values (v_org, v_session, v_arm_a, v_maths, v_staff);
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id)
    values (v_org, v_session, v_arm_b, v_maths, v_staff);
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Chidi', 'Eze') returning id into v_student;
  insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_student, v_session, v_arm_a);
  insert into public.student_subjects (organization_id, student_id, session_id, subject_id) values (v_org, v_student, v_session, v_french);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);

  -- 01 a subject with a teacher stays on the arm, with the teacher named
  begin
    delete from public.arm_subjects where arm_id = v_arm_a and subject_id = v_maths;
    v_log := v_log || E'\nFAIL 01 removed a subject a teacher is assigned to';
  exception when raise_exception then
    v_log := v_log || E'\n' || case when sqlerrm like 'Ada Bello teaches Mathematics in JSS 1A%' then 'PASS' else 'FAIL' end
      || ' 01 a taught subject stays [' || sqlerrm || ']';
  end;

  -- 02 an optional subject students chose stays on the arm
  begin
    delete from public.arm_subjects where arm_id = v_arm_a and subject_id = v_french;
    v_log := v_log || E'\nFAIL 02 removed a subject students chose';
  exception when raise_exception then
    v_log := v_log || E'\n' || case when sqlerrm like '1 student in JSS 1A chose French%' then 'PASS' else 'FAIL' end
      || ' 02 a chosen subject stays [' || sqlerrm || ']';
  end;

  -- 03 an unused subject comes off the arm
  delete from public.arm_subjects where arm_id = v_arm_a and subject_id = v_art;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 03 an unused subject comes off the arm';

  -- 04 the app can see which links are in use
  select u.teacher_name, u.choices into v_teacher, v_choices
    from public.arm_subject_usage(v_org) u where u.arm_id = v_arm_a and u.subject_id = v_french;
  v_log := v_log || E'\n' || case when v_teacher is null and v_choices = 1 then 'PASS' else 'FAIL' end
    || ' 04 usage shows the choice on French';
  select u.teacher_name into v_teacher
    from public.arm_subject_usage(v_org) u where u.arm_id = v_arm_a and u.subject_id = v_maths;
  v_log := v_log || E'\n' || case when v_teacher = 'Ada Bello' then 'PASS' else 'FAIL' end
    || ' 05 usage names the Maths teacher';

  -- 06 deleting a whole arm still takes its subjects and teaching with it
  delete from public.class_arms where id = v_arm_b;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1
      and not exists (select 1 from public.arm_subjects where arm_id = v_arm_b)
    then 'PASS' else 'FAIL' end || ' 06 deleting an arm still removes its subjects';

  -- 07 another school can't read this school's usage
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_stranger","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.arm_subject_usage(v_org);
    v_log := v_log || E'\nFAIL 07 a stranger read the usage';
  exception when insufficient_privilege then
    v_log := v_log || E'\nPASS 07 a stranger cannot read the usage';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('16_keep_taught_arm_subjects_test', v_log);
end;
$test$;

-- ── 17_person_delete_and_principal_logins_test.sql ──
do $test$
declare
  v_log     text := '';
  v_n       int;
  v_org     uuid;
  v_claim   text;
  v_code    text;
  v_status  text;
  v_owner   public.organization_members;
  v_member  public.organization_members;
  v_owner_staff uuid;
  v_pat     uuid;
  v_ada     uuid;
  v_bea     uuid;
  v_tee     uuid;
  v_stu     uuid;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: a school, its owner, a principal and three staff ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim from public.create_organization('Test School', 'TST') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_owner := public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  select s.id into v_owner_staff from public.staff s where s.member_id = v_owner.id;
  insert into public.staff (organization_id, first_name, last_name, job_title) values (v_org, 'Pat', 'Principal', 'Principal') returning id into v_pat;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Teacher') returning id into v_ada;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Bea', 'Bursar') returning id into v_bea;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Tee', 'Teacher') returning id into v_tee;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Sam', 'Student') returning id into v_stu;
  v_code := public.invite_staff(v_pat, 'principal');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_code);

  -- 01 a principal issues a teacher login and it links the staff record
  v_code := public.invite_staff(v_ada, 'teacher');
  execute 'reset role';
  select count(*) into v_n from public.staff s join public.organization_members m on m.id = s.member_id
    where s.id = v_ada and m.role = 'teacher' and m.status = 'invited' and m.claim_code = v_code;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 01 principal issues a teacher login';

  -- 02 a principal can't issue an admin login
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.invite_staff(v_tee, 'admin');
    v_log := v_log || E'\nFAIL 02 principal issued an admin login';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 02 principal cannot issue admin [' || sqlerrm || ']';
  end;

  -- 03 a principal can't turn the owner's admin invite into something else
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.invite_staff(v_bea, 'admin');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.invite_staff(v_bea, 'bursar');
    v_log := v_log || E'\nFAIL 03 principal changed an admin invite';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 03 principal cannot change an admin invite [' || sqlerrm || ']';
  end;

  -- 04 principals still can't issue student logins
  begin
    perform public.invite_student(v_stu);
    v_log := v_log || E'\nFAIL 04 principal issued a student login';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04 principal cannot issue student logins [' || sqlerrm || ']';
  end;

  -- 05 deleting a staff record with an unclaimed invite deletes the invite
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  delete from public.staff where id = v_ada;
  execute 'reset role';
  select count(*) into v_n from public.organization_members where claim_code = v_code;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 05 unclaimed invite removed with the record [' || v_n || ' left]';

  -- 06 deleting a staff record with an active login suspends the login
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_code := public.invite_staff(v_tee, 'teacher');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_code);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  delete from public.staff where id = v_tee;
  execute 'reset role';
  select m.status::text into v_status from public.organization_members m where m.id = v_member.id;
  v_log := v_log || E'\n' || case when v_status = 'suspended' then 'PASS' else 'FAIL' end || ' 06 active login suspended [' || coalesce(v_status, 'gone') || ']';

  -- 07 the suspended teacher no longer sees the school's data
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 07 suspended login sees no staff [' || v_n || ']';

  -- 08 deleting a student with an active login suspends it
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_code := public.invite_student(v_stu);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_student","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_code);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  delete from public.students where id = v_stu;
  execute 'reset role';
  select m.status::text into v_status from public.organization_members m where m.id = v_member.id;
  v_log := v_log || E'\n' || case when v_status = 'suspended' then 'PASS' else 'FAIL' end || ' 08 student login suspended [' || coalesce(v_status, 'gone') || ']';

  -- 09 the owner's own staff record can't be deleted
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    delete from public.staff where id = v_owner_staff;
    v_log := v_log || E'\nFAIL 09 owner staff record deleted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' then 'PASS' else 'FAIL' end || ' 09 owner staff record kept [' || sqlerrm || ']';
  end;

  -- 10 a record with no login deletes as before
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'No', 'Login') returning id into v_pat;
  delete from public.staff where id = v_pat;
  execute 'reset role';
  select count(*) into v_n from public.staff where id = v_pat;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 10 record without a login deletes';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('17_person_delete_and_principal_logins_test', v_log);
end;
$test$;

