do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_org2   uuid;
  v_claim  text;
  v_claim2 text;
  v_code   text;
  v_member public.organization_members;
  v_owner_staff uuid;
  v_pat    uuid;
  v_ada    uuid;
  v_bola   uuid;
  v_tee    uuid;
  v_lola   uuid;
  v_eze    uuid;
  v_parent uuid;
  v_res    jsonb;
  v_row    jsonb;
