  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  select s.id into v_owner_staff from public.staff s where s.member_id = v_member.id;

  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type, phone)
    values (v_org, 'Pat', 'Principal', 'Principal', 'non_teaching', '08035550142') returning id into v_pat;
  insert into public.staff (organization_id, first_name, middle_name, last_name, job_title, staff_number, email)
    values (v_org, 'Ada', 'Ngozi', 'Teacher', 'Teacher', 'SPECIAL-42', 'ada@school.ng') returning id into v_ada;
  insert into public.staff (organization_id, first_name, last_name, staff_type, phone)
    values (v_org, 'Bola', 'Nologin', 'non_teaching', '+234 803 555 0143') returning id into v_bola;
  insert into public.staff (organization_id, first_name, last_name, job_title, phone)
    values (v_org, 'Tee', 'Teacher', 'Teacher', '803-555-0144') returning id into v_tee;
  insert into public.staff (organization_id, first_name, last_name, status)
    values (v_org, 'Lola', 'Leave', 'on_leave') returning id into v_lola;
  insert into public.staff (organization_id, first_name, last_name, staff_type, status)
    values (v_org, 'Eze', 'Exited', 'non_teaching', 'exited') returning id into v_eze;
  insert into public.parents (organization_id, first_name, last_name, phone)
    values (v_org, 'Pam', 'Parent', '08030000000') returning id into v_parent;

  -- Pat: principal on the app
  v_code := public.invite_staff(v_pat, 'principal');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_code);

  -- Tee: teacher who joined, then was suspended
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_code := public.invite_staff(v_tee, 'teacher');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_code);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  update public.organization_members set status = 'suspended' where id = v_member.id;

  -- Ada: teacher invite nobody has used (code ready)
  perform public.invite_staff(v_ada, 'teacher');

  -- Pam: a parent on the app
  v_code := public.invite_parent(v_parent);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_code);

  -- distinct created_at (inserts in one transaction share now())
  execute 'reset role';
  update public.staff s set created_at = now() - make_interval(days => x.d)
  from (values (v_owner_staff, 7), (v_pat, 6), (v_ada, 5), (v_bola, 4), (v_tee, 3), (v_lola, 2), (v_eze, 1)) as x(id, d)
  where s.id = x.id;

  -- everything below runs as the owner unless it says otherwise
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 01 no filters: everyone, owner first, then by name; one page
  v_res := public.list_staff(v_org);
  v_got := pg_temp.names(v_res);
  v_log := v_log || E'\n' || case when v_got = 'Olu,Ada,Bola,Eze,Lola,Pat,Tee'
                                    and (v_res ->> 'total')::int = 7
                                    and v_res -> 'next_cursor' = 'null'::jsonb
                                  then 'PASS' else 'FAIL' end || ' 01 unfiltered, owner first then name [' || v_got || ']';

  -- 02 newest first
  v_got := pg_temp.names(public.list_staff(v_org, p_sort => 'newest'));
  v_log := v_log || E'\n' || case when v_got = 'Eze,Lola,Tee,Bola,Ada,Pat,Olu' then 'PASS' else 'FAIL' end
           || ' 02 newest first [' || v_got || ']';

  -- 03 search: name part, middle name, two words, case
  v_got := pg_temp.names(public.list_staff(v_org, p_search => 'TEACH'));
  v_ok := v_got = 'Ada,Tee';
  v_got := pg_temp.names(public.list_staff(v_org, p_search => 'ngoz'));
  v_ok := v_ok and v_got = 'Ada';
  v_got := pg_temp.names(public.list_staff(v_org, p_search => '  ada   teacher '));
  v_ok := v_ok and v_got = 'Ada';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 search by name part, middle name, words';

  -- 04 search: phone in every format finds the same person, however it was saved
  v_ok := true;
  for v_phone in
    select * from (values
      ('0803 555 0142', 'Pat'), ('8035550142', 'Pat'), ('+2348035550142', 'Pat'),
      ('0803 555 0143', 'Bola'), ('8035550143', 'Bola'), ('+2348035550143', 'Bola'),
      ('0803 555 0144', 'Tee'), ('8035550144', 'Tee'), ('+234 803 555 0144', 'Tee'),
      ('555 014', 'Bola,Pat,Tee'), ('0144', 'Tee')
    ) as t(term, expect)
  loop
    v_got := pg_temp.names(public.list_staff(v_org, p_search => v_phone.term));
    if v_got <> v_phone.expect then
      v_ok := false;
      v_log := v_log || E'\n   phone "' || v_phone.term || '" gave [' || v_got || ']';
    end if;
  end loop;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 04 phone variants match';

  -- 05 search: staff number, generated number, email; LIKE wildcards are literal
  v_ok := pg_temp.names(public.list_staff(v_org, p_search => 'special-4')) = 'Ada';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_search => 'ADA@SCHOOL')) = 'Ada';
  v_ok := v_ok and (public.list_staff(v_org, p_search => 'tst/stf/') ->> 'total')::int = 6;
  v_ok := v_ok and (public.list_staff(v_org, p_search => '%') ->> 'total')::int = 0;
  v_ok := v_ok and (public.list_staff(v_org, p_search => '_') ->> 'total')::int = 0;
  v_ok := v_ok and (public.list_staff(v_org, p_search => '   ') ->> 'total')::int = 7;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 05 staff number, email, literal % and _, blank search';

  -- 06 each login filter
  v_ok := pg_temp.names(public.list_staff(v_org, p_login => 'on_app')) = 'Olu,Pat';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_login => 'code_ready')) = 'Ada';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_login => 'not_on_app')) = 'Bola,Eze,Lola';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_login => 'suspended')) = 'Tee';
  v_ok := v_ok and (public.list_staff(v_org, p_login => 'all') ->> 'total')::int = 7;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 06 login filters';

  -- 07 roles: only people with a login, any login status
  v_ok := pg_temp.names(public.list_staff(v_org, p_roles => array['teacher']::public.member_role[])) = 'Ada,Tee';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_roles => array['owner', 'principal']::public.member_role[])) = 'Olu,Pat';
  v_ok := v_ok and (public.list_staff(v_org, p_roles => array['bursar']::public.member_role[]) ->> 'total')::int = 0;
  v_ok := v_ok and (public.list_staff(v_org, p_roles => array[]::public.member_role[]) ->> 'total')::int = 7;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 07 roles filter';

  -- 08 staff type
  v_ok := pg_temp.names(public.list_staff(v_org, p_staff_type => 'non_teaching')) = 'Olu,Bola,Eze,Pat';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_staff_type => 'teaching')) = 'Ada,Lola,Tee';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 08 staff type';

  -- 09 record statuses: null and {} are all
  v_ok := pg_temp.names(public.list_staff(v_org, p_statuses => array['active']::public.staff_status[])) = 'Olu,Ada,Bola,Pat,Tee';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_statuses => array['on_leave', 'exited']::public.staff_status[])) = 'Eze,Lola';
  v_ok := v_ok and (public.list_staff(v_org, p_statuses => array[]::public.staff_status[]) ->> 'total')::int = 7;
  v_ok := v_ok and (public.list_staff(v_org, p_statuses => null) ->> 'total')::int = 7;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 09 record statuses';

  -- 10 pages of 2 by name: no duplicates or gaps, cursor null at the end
  v_got := '';
  v_cursor := null;
  v_pages := 0;
  loop
    v_res := public.list_staff(v_org, p_limit => 2, p_cursor => v_cursor);
    v_pages := v_pages + 1;
    v_got := v_got || case when v_got = '' then '' else ',' end || pg_temp.names(v_res);
    v_cursor := v_res ->> 'next_cursor';
    exit when v_cursor is null or v_pages > 10;
  end loop;
  v_log := v_log || E'\n' || case when v_got = 'Olu,Ada,Bola,Eze,Lola,Pat,Tee' and v_pages = 4 then 'PASS' else 'FAIL' end
           || ' 10 name pages of 2 [' || v_got || ' in ' || v_pages || ' pages]';

  -- 11 pages of 3, newest, with a filter; a full last page still ends with null
  v_got := '';
  v_cursor := null;
  v_pages := 0;
  loop
    v_res := public.list_staff(v_org, p_sort => 'newest', p_limit => 3, p_cursor => v_cursor);
    v_pages := v_pages + 1;
    v_got := v_got || case when v_got = '' then '' else ',' end || pg_temp.names(v_res);
    v_cursor := v_res ->> 'next_cursor';
    exit when v_cursor is null or v_pages > 10;
  end loop;
  v_ok := v_got = 'Eze,Lola,Tee,Bola,Ada,Pat,Olu' and v_pages = 3;
  v_res := public.list_staff(v_org, p_statuses => array['active']::public.staff_status[], p_limit => 5);
  v_ok := v_ok and jsonb_array_length(v_res -> 'rows') = 5 and v_res -> 'next_cursor' = 'null'::jsonb;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 11 newest pages of 3, exact last page [' || v_got || ']';

  -- 12 counts ignore the login filter but follow status; total follows everything
  v_res := public.list_staff(v_org, p_login => 'suspended', p_statuses => array['active']::public.staff_status[]);
  v_log := v_log || E'\n' || case when pg_temp.names(v_res) = 'Tee'
                                    and (v_res ->> 'total')::int = 1
                                    and v_res -> 'counts' = '{"all":5,"on_app":2,"code_ready":1,"not_on_app":1,"suspended":1}'::jsonb
                                  then 'PASS' else 'FAIL' end || ' 12 counts ignore login filter ' || (v_res -> 'counts')::text;

  -- 13 counts follow search, type and roles
  v_res := public.list_staff(v_org, p_search => 'teacher', p_login => 'on_app');
  v_ok := (v_res ->> 'total')::int = 0
      and v_res -> 'counts' = '{"all":2,"on_app":0,"code_ready":1,"not_on_app":0,"suspended":1}'::jsonb;
  v_res := public.list_staff(v_org, p_staff_type => 'non_teaching', p_roles => array['owner', 'principal']::public.member_role[]);
  v_ok := v_ok and v_res -> 'counts' = '{"all":2,"on_app":2,"code_ready":0,"not_on_app":0,"suspended":0}'::jsonb;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 13 counts follow search, type and roles';

  -- 14 row shape: what StaffMember.fromJson reads, no private details (and, since
  -- migration 37, a null `teaching` key)
  v_res := public.list_staff(v_org, p_search => 'ngozi');
  v_row := v_res -> 'rows' -> 0;
  v_ok := (select array_agg(k order by k) from jsonb_object_keys(v_row) k)
          = array['created_at', 'email', 'first_name', 'gender', 'id', 'job_title', 'last_name', 'member', 'member_id',
                  'middle_name', 'phone', 'photo_url', 'staff_number', 'staff_type', 'status', 'teaching']
      -- migration 37: `teaching` is there but null unless a subject or class filter is on
      and v_row -> 'teaching' = 'null'::jsonb
      and (select array_agg(k order by k) from jsonb_object_keys(v_row -> 'member') k)
          = array['claim_code', 'clerk_user_id', 'created_at', 'id', 'joined_at', 'role', 'status']
      and v_row ->> 'id' = v_ada::text
      and v_row -> 'member' ->> 'role' = 'teacher'
      and v_row -> 'member' ->> 'status' = 'invited'
      and length(v_row -> 'member' ->> 'claim_code') = 8
      and v_row ->> 'member_id' = v_row -> 'member' ->> 'id';
  v_row := (public.list_staff(v_org, p_search => 'bola') -> 'rows' -> 0);
  v_ok := v_ok and v_row -> 'member' = 'null'::jsonb;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 14 row keys, member embedded or null';

  -- 15 limit is clamped to 1..100
  v_res := public.list_staff(v_org, p_limit => 0);
  v_ok := jsonb_array_length(v_res -> 'rows') = 1 and v_res ->> 'next_cursor' is not null;
  v_res := public.list_staff(v_org, p_limit => -5);
  v_ok := v_ok and jsonb_array_length(v_res -> 'rows') = 1;
  v_res := public.list_staff(v_org, p_limit => 1000);
  v_ok := v_ok and jsonb_array_length(v_res -> 'rows') = 7 and v_res -> 'next_cursor' = 'null'::jsonb;
  v_res := public.list_staff(v_org, p_limit => null);
  v_ok := v_ok and jsonb_array_length(v_res -> 'rows') = 7;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 15 limit clamped';

  -- 16 bad arguments are refused with 22023
  v_ok := true;
  begin
    perform public.list_staff(v_org, p_login => 'everyone');
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = '22023';
  end;
  begin
    perform public.list_staff(v_org, p_sort => 'oldest');
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = '22023';
  end;
  begin
    perform public.list_staff(v_org, p_cursor => 'not a cursor!');
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = '22023';
  end;
  begin
    -- a name cursor used with the newest sort
    v_cursor := public.list_staff(v_org, p_limit => 2) ->> 'next_cursor';
    perform public.list_staff(v_org, p_sort => 'newest', p_cursor => v_cursor);
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = '22023';
  end;
  begin
    perform public.list_staff(null);
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = '22023';
  end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 16 bad login, sort, cursor and school refused';

  -- 17 a parent sees every profile but no one's login
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_res := public.list_staff(v_org);
  v_log := v_log || E'\n' || case when (v_res ->> 'total')::int = 7
                                    and not exists (select 1 from jsonb_array_elements(v_res -> 'rows') r
                                                    where r -> 'member' <> 'null'::jsonb)
                                    and (v_res -> 'counts' ->> 'not_on_app')::int = 7
                                  then 'PASS' else 'FAIL' end || ' 17 parent sees staff, member null [' || pg_temp.names(v_res) || ']';

  -- 18 another school's owner, a stranger and the suspended teacher get nothing
  v_ok := true;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_res := public.list_staff(v_org);
  v_ok := (v_res ->> 'total')::int = 0 and v_res -> 'rows' = '[]'::jsonb and (v_res -> 'counts' ->> 'all')::int = 0;
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org2)) = 'Bee';
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_stranger","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_ok := v_ok and (public.list_staff(v_org) ->> 'total')::int = 0;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_ok := v_ok and (public.list_staff(v_org) ->> 'total')::int = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 18 other school, stranger and suspended login see nothing';

  -- 19 anon can't call it
  execute 'reset role';
  execute 'set local role anon';
  begin
    perform public.list_staff(v_org);
    v_log := v_log || E'\nFAIL 19 anon called list_staff';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 19 anon refused [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('18_staff_list_rpc_test', v_log);
end;
$test$;

-- ── 19_register_student_access_test.sql ──
do $test$
declare
  v_log     text := '';
  v_ok      boolean;
  v_n       int;
  v_org     uuid;  v_claim  text;
  v_org2    uuid;  v_claim2 text;
  v_teacher_claim text;
  v_bursar_claim  text;
  v_jss1    uuid;
  v_jss1a   uuid;
  v_jss1b   uuid;
  v_old     uuid;  -- closed
  v_now     uuid;  -- current
  v_now_term uuid;
  v_optional   uuid;  -- optional on JSS 1A
  v_compulsory uuid;  -- compulsory on JSS 1A
  v_not_offered uuid; -- in the school, not on JSS 1A
  v_pam     uuid;
  v_oscar   uuid;
  v_res     jsonb;
  v_student uuid;
  v_new_parent uuid;
  v_students_before int;
  v_parents_before  int;
  v_links_before    int;
  v_one_parent jsonb;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: two schools ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');
  insert into public.parents (organization_id, first_name, last_name, phone)
    values (v_org2, 'Oscar', 'Elsewhere', '08039999999') returning id into v_oscar;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'teacher')
    returning claim_code into v_teacher_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')
    returning claim_code into v_bursar_claim;

  -- structure and curriculum
  perform public.create_standard_structure(v_org);
  select id into v_jss1 from public.classes where organization_id = v_org and name = 'JSS 1';
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'A') returning id into v_jss1a;
  insert into public.class_arms (organization_id, class_id, name, is_active) values (v_org, v_jss1, 'B', false) returning id into v_jss1b;
  perform public.create_standard_subjects(v_org);
  select subject_id into v_optional   from public.arm_subjects where arm_id = v_jss1a and not is_compulsory limit 1;
  select subject_id into v_compulsory from public.arm_subjects where arm_id = v_jss1a and is_compulsory limit 1;
  select s.id into v_not_offered from public.subjects s
    where s.organization_id = v_org
      and not exists (select 1 from public.arm_subjects a where a.arm_id = v_jss1a and a.subject_id = s.id)
    limit 1;

  -- calendar: last year (ended, closed) and this year (current, with a current term)
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2024/25', '2024-09-09', '2025-07-18') returning id into v_old;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, 'This year', current_date - 30, current_date + 300) returning id into v_now;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_now, 'First term', 1, current_date - 30, current_date + 60) returning id into v_now_term;
  perform public.set_current_term(v_now_term);
  perform public.close_session(v_old);

  insert into public.parents (organization_id, first_name, last_name, phone)
    values (v_org, 'Pam', 'Parent', '0803 000 0000') returning id into v_pam;

  -- teacher and bursar join
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_teacher_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);

  -- the usual parents list: Pam (existing) as primary
  v_one_parent := jsonb_build_array(jsonb_build_object('parent_id', v_pam, 'relationship', 'mother', 'is_primary_contact', true));

  -- everything below runs as the owner unless it says otherwise
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 01 a leader registers a student: existing parent + new parent, current session, one optional subject
  v_res := public.register_student(
    p_organization_id      => v_org,
    p_first_name           => 'Chidi',
    p_last_name            => 'Okafor',
    p_parents              => jsonb_build_array(
                                jsonb_build_object('parent_id', v_pam, 'relationship', 'mother', 'is_primary_contact', true),
                                jsonb_build_object('first_name', 'Emeka', 'last_name', 'Okafor', 'phone', '08035550143',
                                                   'title', 'Mr', 'gender', 'male', 'email', 'emeka@example.ng',
                                                   'occupation', 'Engineer', 'relationship', 'father',
                                                   'is_primary_contact', false)),
    p_arm_id               => v_jss1a,
    p_optional_subject_ids => array[v_optional, v_optional],
    p_gender               => 'male',
    p_date_of_birth        => '2014-03-02',
    p_genotype             => 'AA'
  );
  v_student    := (v_res -> 'student' ->> 'id')::uuid;
  v_new_parent := (v_res -> 'parent_ids' ->> 1)::uuid;
  v_ok := v_student is not null
      and v_res -> 'student' ->> 'admission_number' like 'TST/%'
      and v_res -> 'student' ->> 'status' = 'active'
      and jsonb_array_length(v_res -> 'parent_ids') = 2
      and (v_res -> 'parent_ids' ->> 0)::uuid = v_pam
      and (v_res -> 'placement' ->> 'session_id')::uuid = v_now
      and (v_res -> 'placement' ->> 'arm_id')::uuid = v_jss1a
      and v_res -> 'subject_ids' = jsonb_build_array(v_optional);
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 01 leader registers a student [' || coalesce(v_res -> 'student' ->> 'admission_number', 'no student') || ']';

  -- 02 every row was written
  v_ok := exists (select 1 from public.students where id = v_student and first_name = 'Chidi')
      and exists (select 1 from public.student_private_details where student_id = v_student
                    and date_of_birth = '2014-03-02' and genotype = 'AA')
      and exists (select 1 from public.parents where id = v_new_parent and organization_id = v_org
                    and first_name = 'Emeka' and phone = '08035550143' and title = 'Mr' and gender = 'male')
      and exists (select 1 from public.parent_private_details where parent_id = v_new_parent
                    and email = 'emeka@example.ng' and occupation = 'Engineer')
      and (select count(*) from public.student_parents where student_id = v_student) = 2
      and exists (select 1 from public.student_parents where student_id = v_student and parent_id = v_pam
                    and relationship = 'mother' and is_primary_contact)
      and exists (select 1 from public.student_parents where student_id = v_student and parent_id = v_new_parent
                    and relationship = 'father' and not is_primary_contact)
      and exists (select 1 from public.student_placements where student_id = v_student
                    and session_id = v_now and arm_id = v_jss1a)
      and (select count(*) from public.student_subjects where student_id = v_student) = 1
      and exists (select 1 from public.student_subjects where student_id = v_student
                    and session_id = v_now and subject_id = v_optional);
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 02 student, details, new parent, links, placement and subject all saved';

  -- 03 explicit session and no optional subjects (a sibling reusing Pam)
  v_res := public.register_student(v_org, 'Ada', 'Okafor', v_one_parent, v_jss1a, v_now);
  v_ok := (v_res -> 'placement' ->> 'session_id')::uuid = v_now
      and v_res -> 'subject_ids' = '[]'::jsonb
      and (select count(*) from public.student_parents where parent_id = v_pam) = 2;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 sibling reuses an existing parent, explicit session, no subjects';

  -- snapshot for the "nothing kept" checks below
  select count(*) into v_students_before from public.students where organization_id = v_org;
  select count(*) into v_parents_before  from public.parents  where organization_id = v_org;
  select count(*) into v_links_before    from public.student_parents where organization_id = v_org;

  -- 04 teacher refused
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.register_student(v_org, 'Tee', 'Kid', v_one_parent, v_jss1a);
    v_log := v_log || E'\nFAIL 04 teacher registered a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04 teacher refused [' || sqlerrm || ']';
  end;

  -- 05 bursar refused
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.register_student(v_org, 'Bee', 'Kid', v_one_parent, v_jss1a);
    v_log := v_log || E'\nFAIL 05 bursar registered a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 05 bursar refused [' || sqlerrm || ']';
  end;

  -- 06 another school's owner refused
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.register_student(v_org, 'Xen', 'Kid', v_one_parent, v_jss1a);
    v_log := v_log || E'\nFAIL 06 other school''s owner registered a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06 other school''s owner refused [' || sqlerrm || ']';
  end;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 07 closed session refused
  begin
    perform public.register_student(v_org, 'Old', 'Kid', v_one_parent, v_jss1a, v_old);
    v_log := v_log || E'\nFAIL 07 registered into a closed session';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%closed%' then 'PASS' else 'FAIL' end || ' 07 closed session refused [' || sqlerrm || ']';
  end;

  -- 08 compulsory subject refused
  begin
    perform public.register_student(v_org, 'Com', 'Kid', v_one_parent, v_jss1a, null, array[v_compulsory]);
    v_log := v_log || E'\nFAIL 08 compulsory subject accepted as optional';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' and sqlerrm like '%compulsory%' then 'PASS' else 'FAIL' end || ' 08 compulsory subject refused [' || sqlerrm || ']';
  end;

  -- 09 subject the arm doesn't offer refused
  begin
    perform public.register_student(v_org, 'Off', 'Kid', v_one_parent, v_jss1a, null, array[v_not_offered]);
    v_log := v_log || E'\nFAIL 09 subject not offered to the arm accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' and sqlerrm like '%isn''t offered%' then 'PASS' else 'FAIL' end || ' 09 subject not offered refused [' || sqlerrm || ']';
  end;

  -- 10 no primary contact refused
  begin
    perform public.register_student(v_org, 'No', 'Primary',
      jsonb_build_array(jsonb_build_object('parent_id', v_pam, 'relationship', 'mother', 'is_primary_contact', false)), v_jss1a);
    v_log := v_log || E'\nFAIL 10 registered with no primary contact';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' and sqlerrm like '%primary contact%' then 'PASS' else 'FAIL' end || ' 10 no primary contact refused [' || sqlerrm || ']';
  end;

  -- 11 two primary contacts refused
  begin
    perform public.register_student(v_org, 'Two', 'Primaries',
      jsonb_build_array(
        jsonb_build_object('parent_id', v_pam, 'relationship', 'mother', 'is_primary_contact', true),
        jsonb_build_object('first_name', 'Second', 'last_name', 'Parent', 'phone', '08031111111',
                           'relationship', 'father', 'is_primary_contact', true)), v_jss1a);
    v_log := v_log || E'\nFAIL 11 registered with two primary contacts';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' and sqlerrm like 'Only one parent%' then 'PASS' else 'FAIL' end || ' 11 two primary contacts refused [' || sqlerrm || ']';
  end;

  -- 12 no parents refused
  begin
    perform public.register_student(v_org, 'No', 'Parents', '[]'::jsonb, v_jss1a);
    v_log := v_log || E'\nFAIL 12 registered with no parents';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' and sqlerrm like '%at least one parent%' then 'PASS' else 'FAIL' end || ' 12 no parents refused [' || sqlerrm || ']';
  end;

  -- 13 another school's parent refused
  begin
    perform public.register_student(v_org, 'Cross', 'School',
      jsonb_build_array(jsonb_build_object('parent_id', v_oscar, 'relationship', 'father', 'is_primary_contact', true)), v_jss1a);
    v_log := v_log || E'\nFAIL 13 linked another school''s parent';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0002' then 'PASS' else 'FAIL' end || ' 13 other school''s parent refused [' || sqlerrm || ']';
  end;

  -- 14 the same parent twice refused
  begin
    perform public.register_student(v_org, 'Dup', 'Parent',
      jsonb_build_array(
        jsonb_build_object('parent_id', v_pam, 'relationship', 'mother', 'is_primary_contact', true),
        jsonb_build_object('parent_id', v_pam, 'relationship', 'guardian', 'is_primary_contact', false)), v_jss1a);
    v_log := v_log || E'\nFAIL 14 same parent listed twice accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' and sqlerrm like '%listed twice%' then 'PASS' else 'FAIL' end || ' 14 duplicate parent refused [' || sqlerrm || ']';
  end;

  -- 15 a NEW parent with an existing parent's phone (other format) is refused, not merged
  begin
    perform public.register_student(v_org, 'Same', 'Phone',
      jsonb_build_array(jsonb_build_object('first_name', 'Pamela', 'last_name', 'Parent', 'phone', '+234 803 000 0000',
                                           'relationship', 'mother', 'is_primary_contact', true)), v_jss1a);
    v_log := v_log || E'\nFAIL 15 new parent with an existing phone accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' and sqlerrm like 'Pam Parent%existing parent%' then 'PASS' else 'FAIL' end || ' 15 existing phone refused, reuse suggested [' || sqlerrm || ']';
  end;

  -- 16 unknown relationship refused
  begin
    perform public.register_student(v_org, 'Bad', 'Relation',
      jsonb_build_array(jsonb_build_object('parent_id', v_pam, 'relationship', 'aunt', 'is_primary_contact', true)), v_jss1a);
    v_log := v_log || E'\nFAIL 16 unknown relationship accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' and sqlerrm like '%father, mother, guardian or other%' then 'PASS' else 'FAIL' end || ' 16 unknown relationship refused [' || sqlerrm || ']';
  end;

  -- 17 switched-off arm, and an arm from another school, refused
  v_ok := true;
  begin
    perform public.register_student(v_org, 'Off', 'Arm', v_one_parent, v_jss1b);
    v_ok := false;
  exception when others then
    v_ok := sqlstate = 'P0001' and sqlerrm like '%switched off%';
  end;
  begin
    perform public.register_student(v_org, 'No', 'Arm', v_one_parent, gen_random_uuid());
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = 'P0002';
  end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 17 switched-off or unknown arm refused';

  -- 17b a class in a switched-off section is refused (migration 32); switching it back on allows it
  update public.sections set is_active = false where id = (select section_id from public.classes where id = v_jss1);
  v_ok := false;
  begin
    perform public.register_student(v_org, 'Off', 'Section', v_one_parent, v_jss1a);
  exception when others then
    v_ok := sqlstate = 'P0001' and sqlerrm like '%section is switched off%';
  end;
  update public.sections set is_active = true where id = (select section_id from public.classes where id = v_jss1);
  v_ok := v_ok
    and (select count(*) from public.students where organization_id = v_org) = v_students_before;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 17b switched-off section refused, nothing kept';

  -- 18 a failure after the first write (bad blood group fails in create_student,
  --    after the student row is inserted) keeps nothing: no student, parent or link
  begin
    perform public.register_student(
      p_organization_id => v_org,
      p_first_name      => 'Roll',
      p_last_name       => 'Back',
      p_parents         => jsonb_build_array(jsonb_build_object('first_name', 'Rita', 'last_name', 'Back',
                             'phone', '08032222222', 'relationship', 'mother', 'is_primary_contact', true)),
      p_arm_id          => v_jss1a,
      p_blood_group     => 'Z+');
    v_log := v_log || E'\nFAIL 18 invalid blood group accepted';
  exception when others then
    v_ok := sqlstate = '23514'
        and (select count(*) from public.students where organization_id = v_org) = v_students_before
        and (select count(*) from public.parents  where organization_id = v_org) = v_parents_before
        and (select count(*) from public.student_parents where organization_id = v_org) = v_links_before
        and not exists (select 1 from public.students where organization_id = v_org and first_name = 'Roll')
        and not exists (select 1 from public.parents where organization_id = v_org and phone = '08032222222');
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 18 failure rolls everything back [' || sqlerrm || ']';
  end;

  -- 19 none of the refusals above kept anything
  v_ok := (select count(*) from public.students where organization_id = v_org) = v_students_before
      and (select count(*) from public.parents  where organization_id = v_org) = v_parents_before
      and (select count(*) from public.student_parents where organization_id = v_org) = v_links_before;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 19 refused calls left no rows behind';

  -- 20 anon can't call it
  execute 'reset role';
  execute 'set local role anon';
  begin
    perform public.register_student(v_org, 'Anon', 'Kid', v_one_parent, v_jss1a);
    v_log := v_log || E'\nFAIL 20 anon called register_student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 20 anon refused [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('19_register_student', v_log);
end;
$test$;

-- ── 20_reorder_score_columns_test.sql ──
do $test$
declare
  v_log     text := '';
  v_ok      boolean;
  v_org     uuid;  v_claim  text;
  v_org2    uuid;  v_claim2 text;
  v_admin_claim     text;
  v_principal_claim text;
  v_vp_claim        text;
  v_bursar_claim    text;
  v_teacher_claim   text;
  v_nursery uuid;
  v_ca1     uuid;
  v_ca2     uuid;
  v_exam    uuid;
  v_obs     uuid;
  v_rhymes  uuid;
  v_drawing uuid;
  v_other_ca1 uuid;
  v_before  text;
  v_after   text;
  v_txt     text;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: two schools ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');
  perform public.create_standard_grading(v_org2);
  select id into v_other_ca1 from public.score_columns where organization_id = v_org2 and section_id is null and name = 'CA 1';

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'admin')
    returning claim_code into v_admin_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')
    returning claim_code into v_principal_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'vice_principal')
    returning claim_code into v_vp_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')
    returning claim_code into v_bursar_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'teacher')
    returning claim_code into v_teacher_claim;

  perform public.create_standard_structure(v_org);
  perform public.create_standard_grading(v_org);
  select id into v_nursery from public.sections where organization_id = v_org and name = 'Nursery';
  select id into v_ca1  from public.score_columns where organization_id = v_org and section_id is null and name = 'CA 1';
  select id into v_ca2  from public.score_columns where organization_id = v_org and section_id is null and name = 'CA 2';
  select id into v_exam from public.score_columns where organization_id = v_org and section_id is null and name = 'Exam';
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'Observation', 40) returning id into v_obs;
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'Rhymes', 30) returning id into v_rhymes;
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'Drawing', 30) returning id into v_drawing;

  -- everyone else joins
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_admin_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_vp","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_vp_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_teacher_claim);

  -- everything below runs as the owner unless it says otherwise
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 01 owner reorders the school's set; it becomes exactly 1..n in the order given
  perform public.reorder_score_columns(v_org, array[v_exam, v_ca1, v_ca2]);
  select string_agg(name || '=' || sort_order, ',' order by sort_order, name) into v_txt
    from public.score_columns where organization_id = v_org and section_id is null;
  v_log := v_log || E'\n' || case when v_txt = 'Exam=1,CA 1=2,CA 2=3' then 'PASS' else 'FAIL' end || ' 01 owner reorders the school''s set to 1..n [' || coalesce(v_txt, 'null') || ']';

  -- 02 no gaps or repeats left behind
  v_ok := (select array_agg(sort_order order by sort_order) from public.score_columns
             where organization_id = v_org and section_id is null) = array[1, 2, 3];
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 02 sort_order has no gaps or repeats';

  -- 03 admin, principal and VP can each reorder it
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.reorder_score_columns(v_org, array[v_ca2, v_exam, v_ca1]);
  select string_agg(name, ',' order by sort_order) into v_txt from public.score_columns where organization_id = v_org and section_id is null;
  v_ok := v_txt = 'CA 2,Exam,CA 1';

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.reorder_score_columns(v_org, array[v_ca1, v_exam, v_ca2]);
  select string_agg(name, ',' order by sort_order) into v_txt from public.score_columns where organization_id = v_org and section_id is null;
  v_ok := v_ok and v_txt = 'CA 1,Exam,CA 2';

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_vp","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.reorder_score_columns(v_org, array[v_ca1, v_ca2, v_exam]);
  select string_agg(name || '=' || sort_order, ',' order by sort_order) into v_txt from public.score_columns where organization_id = v_org and section_id is null;
  v_ok := v_ok and v_txt = 'CA 1=1,CA 2=2,Exam=3';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 admin, principal and VP each reorder the school''s set [' || coalesce(v_txt, 'null') || ']';

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 04 Nursery's own set (all 0 to start) is reordered on its own; the school's set is untouched
  perform public.reorder_score_columns(v_org, array[v_drawing, v_obs, v_rhymes]);
  select string_agg(name || '=' || sort_order, ',' order by sort_order) into v_txt
    from public.score_columns where section_id = v_nursery;
  v_ok := v_txt = 'Drawing=1,Observation=2,Rhymes=3'
      and (select string_agg(name || '=' || sort_order, ',' order by sort_order) from public.score_columns
             where organization_id = v_org and section_id is null) = 'CA 1=1,CA 2=2,Exam=3';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 04 a section''s set reorders independently of the school''s [' || coalesce(v_txt, 'null') || ']';

  -- snapshot of every column in both schools for the "nothing changed" checks below
  execute 'reset role';
  select string_agg(id::text || ':' || sort_order, ',' order by id) into v_before
    from public.score_columns where organization_id in (v_org, v_org2);

  -- 05 bursar refused
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca1]);
    v_log := v_log || E'\nFAIL 05 bursar reordered score columns';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 05 bursar refused [' || sqlerrm || ']';
  end;

  -- 06 teacher refused
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca1]);
    v_log := v_log || E'\nFAIL 06 teacher reordered score columns';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06 teacher refused [' || sqlerrm || ']';
  end;

  -- 07 another school's owner refused
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca1]);
    v_log := v_log || E'\nFAIL 07 other school''s owner reordered score columns';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 07 other school''s owner refused [' || sqlerrm || ']';
  end;

  -- 08 anon can't call it
  execute 'reset role';
  execute 'set local role anon';
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca1]);
    v_log := v_log || E'\nFAIL 08 anon called reorder_score_columns';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08 anon refused [' || sqlerrm || ']';
  end;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 09 a column that doesn't exist refused
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, gen_random_uuid()]);
    v_log := v_log || E'\nFAIL 09 unknown column accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%no longer exists%' then 'PASS' else 'FAIL' end || ' 09 unknown column refused [' || sqlerrm || ']';
  end;

  -- 10 the same column twice refused
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca2, v_ca1]);
    v_log := v_log || E'\nFAIL 10 column listed twice accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%listed twice%' then 'PASS' else 'FAIL' end || ' 10 duplicate column refused [' || sqlerrm || ']';
  end;

  -- 11 another school's column refused, with the same message as an unknown one
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca1, v_other_ca1]);
    v_log := v_log || E'\nFAIL 11 other school''s column accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%no longer exists%' then 'PASS' else 'FAIL' end || ' 11 other school''s column refused [' || sqlerrm || ']';
  end;

  -- 12 the school's and Nursery's columns mixed refused
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, v_ca1, v_obs]);
    v_log := v_log || E'\nFAIL 12 columns from two sets accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%different sets%' then 'PASS' else 'FAIL' end || ' 12 mixed sets refused [' || sqlerrm || ']';
  end;

  -- 13 a list that leaves a column out refused
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca1]);
    v_log := v_log || E'\nFAIL 13 incomplete list accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%missing from the new order%' then 'PASS' else 'FAIL' end || ' 13 column left out refused [' || sqlerrm || ']';
  end;

  -- 14 an empty list (and no list) refused
  v_ok := true;
  begin
    perform public.reorder_score_columns(v_org, '{}'::uuid[]);
    v_ok := false;
  exception when others then
    v_ok := sqlstate = 'P0001' and sqlerrm like '%no score columns to put in order%';
  end;
  begin
    perform public.reorder_score_columns(v_org, null);
    v_ok := false;
  exception when others then
    v_ok := v_ok and sqlstate = 'P0001' and sqlerrm like '%no score columns to put in order%';
  end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 14 empty or null list refused';

  -- 15 a null id in the list refused
  begin
    perform public.reorder_score_columns(v_org, array[v_exam, v_ca2, null]);
    v_log := v_log || E'\nFAIL 15 null id accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%no longer exists%' then 'PASS' else 'FAIL' end || ' 15 null id refused [' || sqlerrm || ']';
  end;

  -- 16 none of the refusals above changed any sort_order, in either school
  execute 'reset role';
  select string_agg(id::text || ':' || sort_order, ',' order by id) into v_after
    from public.score_columns where organization_id in (v_org, v_org2);
  v_log := v_log || E'\n' || case when v_after = v_before then 'PASS' else 'FAIL' end || ' 16 refused calls left every sort_order untouched';

  -- 17 sending the order it already has is fine and changes nothing
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.reorder_score_columns(v_org, array[v_ca1, v_ca2, v_exam]);
  execute 'reset role';
  select string_agg(id::text || ':' || sort_order, ',' order by id) into v_after
    from public.score_columns where organization_id in (v_org, v_org2);
  v_log := v_log || E'\n' || case when v_after = v_before then 'PASS' else 'FAIL' end || ' 17 the current order again is accepted and changes nothing';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('20_reorder_score_columns_test', v_log);
end;
$test$;

-- ── 21_grade_scales_test.sql ──
do $test$
declare
  v_log     text := '';
  v_ok      boolean;
  v_n       int;
  v_org     uuid;  v_claim  text;
  v_org2    uuid;  v_claim2 text;
  v_admin_claim     text;
  v_principal_claim text;
  v_vp_claim        text;
  v_bursar_claim    text;
  v_teacher_claim   text;
  v_nursery   uuid;
  v_primary   uuid;
  v_secondary uuid;
  v_other_primary uuid;
  v_extra     uuid;
  v_nur1a uuid; v_pry1a uuid; v_jss1a uuid;
  v_before  text;
  v_after   text;
  v_txt     text;
  v_msg1    text;
  v_msg2    text;
  v_case    record;
  v_four    constant jsonb := '[
      {"grade": "A", "min_percent": 70, "max_percent": 100, "remark": "Excellent", "is_pass": true},
      {"grade": "B", "min_percent": 55, "max_percent": 69,  "remark": "Good",      "is_pass": true},
      {"grade": "C", "min_percent": 40, "max_percent": 54,  "remark": null,        "is_pass": true},
      {"grade": "F", "min_percent": 0,  "max_percent": 39,  "remark": "Fail",      "is_pass": false}
    ]';
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: two schools ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');
  perform public.create_standard_structure(v_org2);
  perform public.create_standard_grading(v_org2);
  select id into v_other_primary from public.sections where organization_id = v_org2 and name = 'Primary';

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'admin')          returning claim_code into v_admin_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'principal')      returning claim_code into v_principal_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'vice_principal') returning claim_code into v_vp_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')         returning claim_code into v_bursar_claim;
  insert into public.organization_members (organization_id, role) values (v_org, 'teacher')        returning claim_code into v_teacher_claim;

  perform public.create_standard_structure(v_org);
  select id into v_nursery   from public.sections where organization_id = v_org and name = 'Nursery';
  select id into v_primary   from public.sections where organization_id = v_org and name = 'Primary';
  select id into v_secondary from public.sections where organization_id = v_org and name = 'Secondary';
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'Nursery 1' returning id into v_nur1a;
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'Primary 1' returning id into v_pry1a;
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'JSS 1' returning id into v_jss1a;

  -- 01 create_standard_grading still works and writes max_percent
  perform public.create_standard_grading(v_org);
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int, ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where organization_id = v_org and section_id is null;
  v_ok := v_txt = 'A 70-100,B 60-69,C 50-59,D 45-49,E 40-44,F 0-39';
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int, ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_secondary;
  v_ok := v_ok and v_txt = 'A1 75-100,B2 70-74,B3 65-69,C4 60-64,C5 55-59,C6 50-54,D7 45-49,E8 40-44,F9 0-39';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 01 create_standard_grading writes whole-number ranges (school A–F, Secondary WAEC) [' || coalesce(v_txt, 'null') || ']';

  -- everyone else joins
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_admin_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_principal_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_vp","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_vp_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_teacher_claim);

  -- ── privileges ──
  execute 'reset role';

  -- 02 authenticated keeps SELECT only; no write policy is left
  v_ok := has_table_privilege('authenticated', 'public.grade_boundaries', 'SELECT')
      and not has_table_privilege('authenticated', 'public.grade_boundaries', 'INSERT')
      and not has_table_privilege('authenticated', 'public.grade_boundaries', 'UPDATE')
      and not has_table_privilege('authenticated', 'public.grade_boundaries', 'DELETE')
      and not has_column_privilege('authenticated', 'public.grade_boundaries', 'min_percent', 'INSERT')
      and not has_column_privilege('authenticated', 'public.grade_boundaries', 'min_percent', 'UPDATE')
      and not has_table_privilege('anon', 'public.grade_boundaries', 'SELECT')
      and (select count(*) from pg_policies where schemaname = 'public' and tablename = 'grade_boundaries' and cmd <> 'SELECT') = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 02 grade_boundaries: authenticated can only read; no write policies remain';

  -- 03 only authenticated can execute the new functions; the private writers can't be called by clients
  v_ok := has_function_privilege('authenticated', 'public.set_grade_scale(uuid, uuid, jsonb)', 'EXECUTE')
      and has_function_privilege('authenticated', 'public.apply_grade_system(uuid, uuid, text)', 'EXECUTE')
      and has_function_privilege('authenticated', 'public.copy_section_grading(uuid, uuid, uuid, boolean, boolean)', 'EXECUTE')
      and has_function_privilege('authenticated', 'public.remove_section_grade_scale(uuid, uuid)', 'EXECUTE')
      and not has_function_privilege('anon', 'public.set_grade_scale(uuid, uuid, jsonb)', 'EXECUTE')
      and not has_function_privilege('anon', 'public.apply_grade_system(uuid, uuid, text)', 'EXECUTE')
      and not has_function_privilege('anon', 'public.copy_section_grading(uuid, uuid, uuid, boolean, boolean)', 'EXECUTE')
      and not has_function_privilege('anon', 'public.remove_section_grade_scale(uuid, uuid)', 'EXECUTE')
      and not has_function_privilege('authenticated', 'private.replace_grade_scale(uuid, uuid, jsonb)', 'EXECUTE')
      and not has_function_privilege('authenticated', 'private.lock_grading_set(uuid, uuid)', 'EXECUTE')
      and not has_function_privilege('authenticated', 'private.check_grade_scale()', 'EXECUTE');
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 execute: authenticated only; private writers not callable by clients';

  -- 04 direct INSERT, UPDATE and DELETE are refused even for the owner
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_ok := true;
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent, is_pass)
    values (v_org, v_nursery, 'A', 0, 100, true);
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501';
  end;
  begin
    update public.grade_boundaries set remark = 'Top' where organization_id = v_org and section_id is null and grade = 'A';
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501';
  end;
  begin
    delete from public.grade_boundaries where organization_id = v_org and section_id = v_secondary;
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501';
  end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 04 owner can''t insert, update or delete grade rows directly';

  -- ── set_grade_scale ──

  -- 05 owner gives Nursery its own scale; names and remarks are trimmed, a blank remark is null
  perform public.set_grade_scale(v_org, v_nursery, '[
      {"grade": "  A ", "min_percent": 70, "max_percent": 100, "remark": " Excellent ", "is_pass": true},
      {"grade": "B",    "min_percent": 55, "max_percent": 69,  "remark": "  ",          "is_pass": true},
      {"grade": "C",    "min_percent": 40, "max_percent": 54,                            "is_pass": true, "id": "ignored"},
      {"grade": "F",    "min_percent": 0,  "max_percent": 39,  "remark": "Fail",        "is_pass": false}
    ]'::jsonb);
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int || ' ' || coalesce(remark, '-') || ' '
                    || case when is_pass then 'pass' else 'fail' end, ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_nursery;
  v_log := v_log || E'\n' || case when v_txt = 'A 70-100 Excellent pass,B 55-69 - pass,C 40-54 - pass,F 0-39 Fail fail' then 'PASS' else 'FAIL' end
        || ' 05 owner sets Nursery''s scale [' || coalesce(v_txt, 'null') || ']';

  -- 06 sending a new list replaces the whole set (fewer grades, new names)
  perform public.set_grade_scale(v_org, v_nursery, '[
      {"grade": "Pass", "min_percent": 50, "max_percent": 100, "remark": null, "is_pass": true},
      {"grade": "Fail", "min_percent": 0,  "max_percent": 49,  "remark": null, "is_pass": false}
    ]'::jsonb);
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int, ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_nursery;
  v_log := v_log || E'\n' || case when v_txt = 'Pass 50-100,Fail 0-49' then 'PASS' else 'FAIL' end || ' 06 a new list replaces the whole set [' || coalesce(v_txt, 'null') || ']';

  -- 07 admin, principal and VP can each set it; the school-level set (section null) can be set too
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_grade_scale(v_org, v_nursery, v_four);
  v_ok := (select count(*) from public.grade_boundaries where section_id = v_nursery) = 4;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_grade_scale(v_org, v_nursery, '[{"grade": "All", "min_percent": 0, "max_percent": 100, "remark": null, "is_pass": true}]'::jsonb);
  v_ok := v_ok and (select count(*) from public.grade_boundaries where section_id = v_nursery) = 1;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_vp","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.set_grade_scale(v_org, v_nursery, v_four);
  v_ok := v_ok and (select count(*) from public.grade_boundaries where section_id = v_nursery) = 4;
  perform public.set_grade_scale(v_org, null, '[
      {"grade": "A", "min_percent": 70, "max_percent": 100, "remark": "Excellent", "is_pass": true},
      {"grade": "B", "min_percent": 60, "max_percent": 69,  "remark": "Very Good", "is_pass": true},
      {"grade": "C", "min_percent": 50, "max_percent": 59,  "remark": "Good",      "is_pass": true},
      {"grade": "D", "min_percent": 45, "max_percent": 49,  "remark": "Fair",      "is_pass": true},
      {"grade": "E", "min_percent": 40, "max_percent": 44,  "remark": "Pass",      "is_pass": true},
      {"grade": "F", "min_percent": 0,  "max_percent": 39,  "remark": "Weak",      "is_pass": false}
    ]'::jsonb);
  v_ok := v_ok and (select remark from public.grade_boundaries where organization_id = v_org and section_id is null and grade = 'F') = 'Weak'
               and (select count(*) from public.grade_boundaries where section_id = v_secondary) = 9;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 07 admin, principal and VP each set a scale; the school-level set too, other sets untouched';

  -- snapshot of every grade row in both schools for the "nothing changed" checks below
  execute 'reset role';
  select string_agg(id::text || ':' || grade || ':' || min_percent || '-' || max_percent || ':' || coalesce(remark, '') || ':' || is_pass, ',' order by id)
    into v_before from public.grade_boundaries where organization_id in (v_org, v_org2);

  -- 08 bursar, teacher and another school's owner are refused (42501), for every RPC
  for v_case in
    select * from (values ('test_bursar', 'bursar'), ('test_teacher', 'teacher'), ('test_owner_b', 'other school''s owner')) as t (sub, label)
  loop
    execute 'reset role';
    perform set_config('request.jwt.claims', json_build_object('sub', v_case.sub, 'role', 'authenticated')::text, true);
    execute 'set local role authenticated';
    v_ok := true;
    begin perform public.set_grade_scale(v_org, v_nursery, v_four); v_ok := false;
    exception when others then v_ok := v_ok and sqlstate = '42501'; end;
    begin perform public.apply_grade_system(v_org, v_nursery, 'waec'); v_ok := false;
    exception when others then v_ok := v_ok and sqlstate = '42501'; end;
    begin perform public.copy_section_grading(v_org, null, v_nursery, true, true); v_ok := false;
    exception when others then v_ok := v_ok and sqlstate = '42501'; end;
    begin perform public.remove_section_grade_scale(v_org, v_nursery); v_ok := false;
    exception when others then v_ok := v_ok and sqlstate = '42501'; end;
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 08 ' || v_case.label || ' refused by all four RPCs (42501)';
  end loop;

  -- 09 anon can't call any of them
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  v_ok := true;
  begin perform public.set_grade_scale(v_org, v_nursery, v_four); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501'; end;
  begin perform public.apply_grade_system(v_org, v_nursery, 'waec'); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501'; end;
  begin perform public.copy_section_grading(v_org, null, v_nursery, true, true); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501'; end;
  begin perform public.remove_section_grade_scale(v_org, v_nursery); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501'; end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 09 anon refused by all four RPCs';

  -- 10 every bad list is refused with its own message (P0001)
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  for v_case in
    select * from (values
      ('gap',                '[{"grade":"A","min_percent":70,"max_percent":100,"remark":null,"is_pass":true},{"grade":"B","min_percent":0,"max_percent":60,"remark":null,"is_pass":true}]',
                             'Nothing covers 61 to 69. A should start at 61'),
      ('overlap',            '[{"grade":"A","min_percent":60,"max_percent":100,"remark":null,"is_pass":true},{"grade":"B","min_percent":0,"max_percent":65,"remark":null,"is_pass":true}]',
                             'A overlaps the grade below it. A should start at 66'),
      ('doesn''t start at 0', '[{"grade":"A","min_percent":40,"max_percent":100,"remark":null,"is_pass":true}]',
                             'The lowest grade must start at 0. Nothing covers 0 to 39'),
      ('doesn''t end at 100', '[{"grade":"A","min_percent":50,"max_percent":99,"remark":null,"is_pass":true},{"grade":"F","min_percent":0,"max_percent":49,"remark":null,"is_pass":false}]',
                             'The highest grade must end at 100. Nothing covers 100'),
      ('min above max',      '[{"grade":"A","min_percent":50,"max_percent":40,"remark":null,"is_pass":true}]',
                             'Grade A: from (50) is higher than to (40)'),
      ('decimal',            '[{"grade":"A","min_percent":69.5,"max_percent":100,"remark":null,"is_pass":true},{"grade":"F","min_percent":0,"max_percent":69,"remark":null,"is_pass":false}]',
                             'Grade A: from and to must be whole numbers from 0 to 100'),
      ('below 0',            '[{"grade":"A","min_percent":-1,"max_percent":100,"remark":null,"is_pass":true}]',
                             'Grade A: from and to must be whole numbers from 0 to 100'),
      ('duplicate name',     '[{"grade":"A","min_percent":50,"max_percent":100,"remark":null,"is_pass":true},{"grade":" a ","min_percent":0,"max_percent":49,"remark":null,"is_pass":false}]',
                             'Two grades are called a. Give each grade its own name'),
      ('blank name',         '[{"grade":"  ","min_percent":0,"max_percent":100,"remark":null,"is_pass":true}]',
                             'Every grade needs a name'),
      ('name not text',      '[{"grade":7,"min_percent":0,"max_percent":100,"remark":null,"is_pass":true}]',
                             'Every grade needs a name'),
      ('number as text',     '[{"grade":"A","min_percent":"0","max_percent":100,"remark":null,"is_pass":true}]',
                             'Grade A: from and to must be whole numbers from 0 to 100'),
      ('missing max',        '[{"grade":"A","min_percent":0,"remark":null,"is_pass":true}]',
                             'Grade A: from and to must be whole numbers from 0 to 100'),
      ('remark not text',    '[{"grade":"A","min_percent":0,"max_percent":100,"remark":5,"is_pass":true}]',
                             'Grade A: the remark must be text'),
      ('is_pass missing',    '[{"grade":"A","min_percent":0,"max_percent":100,"remark":null}]',
                             'Grade A: say whether it is a pass grade'),
      ('is_pass as text',    '[{"grade":"A","min_percent":0,"max_percent":100,"remark":null,"is_pass":"true"}]',
                             'Grade A: say whether it is a pass grade'),
      ('element not object', '["A"]',
                             'Each grade needs a name, a from and to percentage, a remark and whether it is a pass'),
      ('not a list',         '{"grade":"A","min_percent":0,"max_percent":100,"remark":null,"is_pass":true}',
                             'Send the grade scale as a list of grades'),
      ('empty list',         '[]',
                             'Add at least one grade'),
      ('21 grades',          (select jsonb_agg(jsonb_build_object('grade', 'G' || i, 'min_percent', i * 4, 'max_percent', case when i = 20 then 100 else i * 4 + 3 end,
                                                                  'remark', null, 'is_pass', true))::text
                              from generate_series(0, 20) as i),
                             'A grade scale can have at most 20 grades')
    ) as t (label, grades, expected)
  loop
    begin
      perform public.set_grade_scale(v_org, v_nursery, v_case.grades::jsonb);
      v_log := v_log || E'\nFAIL 10 ' || v_case.label || ' accepted';
    exception when others then
      v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm = v_case.expected then 'PASS' else 'FAIL' end
            || ' 10 ' || v_case.label || ' refused [' || sqlerrm || ']';
    end;
  end loop;

  -- 11 a null list is refused like any other bad shape
  begin
    perform public.set_grade_scale(v_org, v_nursery, null);
    v_log := v_log || E'\nFAIL 11 null list accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm = 'Send the grade scale as a list of grades' then 'PASS' else 'FAIL' end || ' 11 null list refused [' || sqlerrm || ']';
  end;

  -- 12 another school's section gets the same message as a section that doesn't exist; no leak
  v_msg1 := null; v_msg2 := null;
  begin
    perform public.set_grade_scale(v_org, v_other_primary, v_four);
  exception when others then v_msg1 := sqlstate || ' ' || sqlerrm;
  end;
  begin
    perform public.set_grade_scale(v_org, gen_random_uuid(), v_four);
  exception when others then v_msg2 := sqlstate || ' ' || sqlerrm;
  end;
  v_log := v_log || E'\n' || case when v_msg1 = v_msg2 and v_msg1 = 'P0001 That section no longer exists; refresh and try again' then 'PASS' else 'FAIL' end
        || ' 12 another school''s section refused like a missing one [' || coalesce(v_msg1, 'accepted') || ']';

  -- 13 using another school's id (with its own section) is refused as not a leader
  begin
    perform public.set_grade_scale(v_org2, v_other_primary, v_four);
    v_log := v_log || E'\nFAIL 13 owner changed another school''s grades';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 13 another school''s id refused [' || sqlerrm || ']';
  end;

  -- 14 none of the refusals above changed any grade row, in either school
  execute 'reset role';
  select string_agg(id::text || ':' || grade || ':' || min_percent || '-' || max_percent || ':' || coalesce(remark, '') || ':' || is_pass, ',' order by id)
    into v_after from public.grade_boundaries where organization_id in (v_org, v_org2);
  v_log := v_log || E'\n' || case when v_after = v_before then 'PASS' else 'FAIL' end || ' 14 refused calls left every grade row untouched';

  -- ── apply_grade_system ──
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 15 WAEC on Primary and standard on Nursery, exact values
  perform public.apply_grade_system(v_org, v_primary, ' WAEC ');
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int || ' ' || remark || ' ' || case when is_pass then 'pass' else 'fail' end,
                    ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_primary;
  v_ok := v_txt = 'A1 75-100 Excellent pass,B2 70-74 Very Good pass,B3 65-69 Good pass,C4 60-64 Credit pass,C5 55-59 Credit pass,'
               || 'C6 50-54 Credit pass,D7 45-49 Pass pass,E8 40-44 Pass pass,F9 0-39 Fail fail';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 15a WAEC preset on Primary [' || coalesce(v_txt, 'null') || ']';
  perform public.apply_grade_system(v_org, v_nursery, 'standard');
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int || ' ' || remark || ' ' || case when is_pass then 'pass' else 'fail' end,
                    ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_nursery;
  v_ok := v_txt = 'A 70-100 Excellent pass,B 60-69 Very Good pass,C 50-59 Good pass,D 45-49 Fair pass,E 40-44 Pass pass,F 0-39 Fail fail';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 15b standard preset replaces Nursery''s scale [' || coalesce(v_txt, 'null') || ']';

  -- 16 apply_grade_system refusals
  for v_case in
    select * from (values
      ('unknown system',          v_nursery,       'igcse', 'Choose a grade system: waec or standard'),
      ('no system',               v_nursery,       null,    'Choose a grade system: waec or standard'),
      ('school-level set',        null::uuid,      'waec',  'Choose a section to apply the grade system to'),
      ('another school''s section', v_other_primary, 'waec', 'That section no longer exists; refresh and try again'),
      ('missing section',         gen_random_uuid(), 'waec', 'That section no longer exists; refresh and try again')
    ) as t (label, section_id, sys, expected)
  loop
    begin
      perform public.apply_grade_system(v_org, v_case.section_id, v_case.sys);
      v_log := v_log || E'\nFAIL 16 ' || v_case.label || ' accepted';
    exception when others then
      v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm = v_case.expected then 'PASS' else 'FAIL' end
            || ' 16 apply_grade_system: ' || v_case.label || ' refused [' || sqlerrm || ']';
    end;
  end loop;

  -- ── copy_section_grading ──
  -- Nursery gets its own columns first, so copying columns has something to replace.
  insert into public.score_columns (organization_id, section_id, name, max_score, sort_order) values (v_org, v_nursery, 'Observation', 100, 1);

  -- 17a columns only, from the school-level set into Nursery: replaces Nursery's columns, grades untouched
  perform public.copy_section_grading(v_org, null, v_nursery, true, false);
  select string_agg(name || ' ' || max_score::int || ' #' || sort_order, ',' order by sort_order) into v_txt
    from public.score_columns where section_id = v_nursery;
  v_ok := v_txt = 'CA 1 20 #1,CA 2 20 #2,Exam 60 #3'
      and (select count(*) from public.grade_boundaries where section_id = v_nursery and remark = 'Fair') = 1;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 17a columns only: Nursery''s columns replaced by the school''s, its grades kept [' || coalesce(v_txt, 'null') || ']';

  -- 17b grades only, from Secondary into Nursery: Nursery's grades become WAEC, columns untouched
  perform public.copy_section_grading(v_org, v_secondary, v_nursery, false, true);
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int, ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_nursery;
  v_ok := v_txt = 'A1 75-100,B2 70-74,B3 65-69,C4 60-64,C5 55-59,C6 50-54,D7 45-49,E8 40-44,F9 0-39'
      and (select count(*) from public.score_columns where section_id = v_nursery) = 3
      and (select count(*) from public.grade_boundaries where section_id = v_secondary) = 9;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 17b grades only: Nursery''s grades replaced by Secondary''s, source kept [' || coalesce(v_txt, 'null') || ']';

  -- 17c both, from the school-level set into Primary ("Give Primary its own setup"): replaces Primary's WAEC
  perform public.copy_section_grading(v_org, null, v_primary, true, true);
  select string_agg(grade || ' ' || min_percent::int || '-' || max_percent::int || ' ' || remark, ',' order by min_percent desc) into v_txt
    from public.grade_boundaries where section_id = v_primary;
  v_ok := v_txt = 'A 70-100 Excellent,B 60-69 Very Good,C 50-59 Good,D 45-49 Fair,E 40-44 Pass,F 0-39 Weak'
      and (select string_agg(name, ',' order by sort_order) from public.score_columns where section_id = v_primary) = 'CA 1,CA 2,Exam'
      and (select string_agg(name, ',' order by sort_order) from public.score_columns_for_arm(v_pry1a)) = 'CA 1,CA 2,Exam'
      and (public.grade_for(v_pry1a, 30)).remark = 'Weak';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 17c both from the school''s setup: Primary gets its own columns and grades [' || coalesce(v_txt, 'null') || ']';

  -- 17d copying again from another section replaces both kinds again (columns from Nursery, grades from Nursery)
  update public.score_columns set name = 'Test' where section_id = v_nursery and name = 'Exam';
  perform public.copy_section_grading(v_org, v_nursery, v_primary, true, true);
  v_ok := (select string_agg(name, ',' order by sort_order) from public.score_columns where section_id = v_primary) = 'CA 1,CA 2,Test'
      and (select count(*) from public.grade_boundaries where section_id = v_primary) = 9;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 17d a second copy replaces the target''s columns and grades';

  -- snapshot of both kinds before the copy refusals
  execute 'reset role';
  select string_agg(id::text || ':' || grade || ':' || min_percent || '-' || max_percent, ',' order by id)
         || '|' || (select string_agg(id::text || ':' || name || ':' || max_score || ':' || sort_order, ',' order by id)
                      from public.score_columns where organization_id in (v_org, v_org2))
    into v_before from public.grade_boundaries where organization_id in (v_org, v_org2);
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 18 copy refusals (P0001), each changing nothing
  for v_case in
    select * from (values
      ('same section',                 v_nursery,         v_nursery,         true,  true,  'Choose a different set to copy from; a section can''t copy from itself'),
      ('no target',                    v_nursery,         null::uuid,        true,  true,  'Choose the section to copy to'),
      ('nothing chosen',               null::uuid,        v_nursery,         false, false, 'Choose what to copy: score columns, grades or both'),
      ('nothing chosen (nulls)',       null::uuid,        v_nursery,         null,  null,  'Choose what to copy: score columns, grades or both'),
      ('no columns in the source',     v_secondary,       v_nursery,         true,  false, 'There are no score columns to copy from Secondary'),
      ('another school''s target',     null::uuid,        v_other_primary,   true,  true,  'That section no longer exists; refresh and try again'),
      ('another school''s source',     v_other_primary,   v_nursery,         true,  true,  'That section no longer exists; refresh and try again'),
      -- all or nothing: Nursery has columns but, after the next statement, no grades
      ('columns fine, grades missing', v_nursery,         v_secondary,       true,  true,  'There are no grades to copy from Nursery')
    ) as t (label, from_id, to_id, cols, grades, expected)
  loop
    if v_case.label = 'columns fine, grades missing' then
      perform public.remove_section_grade_scale(v_org, v_nursery);
      execute 'reset role';
      select string_agg(id::text || ':' || grade || ':' || min_percent || '-' || max_percent, ',' order by id)
             || '|' || (select string_agg(id::text || ':' || name || ':' || max_score || ':' || sort_order, ',' order by id)
                          from public.score_columns where organization_id in (v_org, v_org2))
        into v_before from public.grade_boundaries where organization_id in (v_org, v_org2);
      perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
      execute 'set local role authenticated';
    end if;
    begin
      perform public.copy_section_grading(v_org, v_case.from_id, v_case.to_id, v_case.cols, v_case.grades);
      v_log := v_log || E'\nFAIL 18 ' || v_case.label || ' accepted';
    exception when others then
      v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm = v_case.expected then 'PASS' else 'FAIL' end
            || ' 18 copy: ' || v_case.label || ' refused [' || sqlerrm || ']';
    end;
  end loop;
  execute 'reset role';
  select string_agg(id::text || ':' || grade || ':' || min_percent || '-' || max_percent, ',' order by id)
         || '|' || (select string_agg(id::text || ':' || name || ':' || max_score || ':' || sort_order, ',' order by id)
                      from public.score_columns where organization_id in (v_org, v_org2))
    into v_after from public.grade_boundaries where organization_id in (v_org, v_org2);
  v_ok := v_after = v_before
      and (select count(*) from public.score_columns where section_id = v_secondary) = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 18z refused copies changed nothing (Secondary got no columns when its grades part failed)';

  -- ── remove_section_grade_scale ──
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 19 Primary goes back to the school's scale; removing again is fine; columns stay
  perform public.remove_section_grade_scale(v_org, v_primary);
  perform public.remove_section_grade_scale(v_org, v_primary);
  v_ok := (select count(*) from public.grade_boundaries where section_id = v_primary) = 0
      and (select count(*) from public.grade_boundaries_for_arm(v_pry1a)) = 6
      and (select count(*) from public.score_columns where section_id = v_primary) = 3;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 19 remove_section_grade_scale: Primary uses the school''s scale again (twice is fine)';

  -- 20 remove refusals
  for v_case in
    select * from (values
      ('school-level set',          null::uuid,        'Choose a section. The school''s own grade scale can''t be removed'),
      ('another school''s section', v_other_primary,   'That section no longer exists; refresh and try again')
    ) as t (label, section_id, expected)
  loop
    begin
      perform public.remove_section_grade_scale(v_org, v_case.section_id);
      v_log := v_log || E'\nFAIL 20 ' || v_case.label || ' accepted';
    exception when others then
      v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm = v_case.expected then 'PASS' else 'FAIL' end
            || ' 20 remove: ' || v_case.label || ' refused [' || sqlerrm || ']';
    end;
  end loop;
  execute 'reset role';  -- count as the table owner: RLS would hide the other school's rows
  v_ok := (select count(*) from public.grade_boundaries where organization_id = v_org2 and section_id is not null) = 9;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 20z the other school''s Secondary scale is untouched';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- ── grade_for rounds first ──
  -- 21 Nursery back on the standard scale: 69.5 → 70 (A), 69.4 → 69 (B), 99.5 → 100 (A), 39.5 → 40 (E), 39.4 → F
  perform public.apply_grade_system(v_org, v_nursery, 'standard');
  v_txt := (public.grade_for(v_nur1a, 69.5)).grade || ',' || (public.grade_for(v_nur1a, 69.4)).grade || ','
        || (public.grade_for(v_nur1a, 99.5)).grade || ',' || (public.grade_for(v_nur1a, 39.5)).grade || ','
        || (public.grade_for(v_nur1a, 39.4)).grade || ',' || (public.grade_for(v_nur1a, 0)).grade || ','
        || (public.grade_for(v_nur1a, 100)).grade;
  v_ok := v_txt = 'A,B,A,E,F,F,A' and round(99.5::numeric) = 100;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 21 grade_for rounds half-up before grading [' || coalesce(v_txt, 'null') || ']';

  -- 22 grading_problems: nothing missing for a complete set
  v_ok := cardinality(public.grading_problems(v_org, v_nursery)) = 0
      and cardinality(public.grading_problems(v_org)) = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 22 grading_problems is empty for complete sets';

  -- ── the deferred scale trigger ──
  -- 23 every set written so far passes the trigger when it is fired now
  begin
    execute 'set constraints all immediate';
    execute 'set constraints all deferred';
    v_log := v_log || E'\nPASS 23 every set the RPCs wrote passes the deferred check';
  exception when others then
    v_log := v_log || E'\nFAIL 23 the deferred check refused a set the RPCs wrote [' || sqlerrm || ']';
  end;

  -- 24 deleting a section cascades to its grades and columns, and the check accepts the now-empty set
  insert into public.sections (organization_id, name) values (v_org, 'Sixth Form') returning id into v_extra;
  perform public.apply_grade_system(v_org, v_extra, 'waec');
  perform public.copy_section_grading(v_org, null, v_extra, true, false);
  begin
    delete from public.sections where id = v_extra;
    execute 'set constraints all immediate';
    execute 'set constraints all deferred';
    v_ok := (select count(*) from public.grade_boundaries where section_id = v_extra) = 0
        and (select count(*) from public.score_columns where section_id = v_extra) = 0;
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 24 deleting a section still cascades its grades and columns';
  exception when others then
    v_log := v_log || E'\nFAIL 24 deleting a section with its own scale was refused [' || sqlerrm || ']';
  end;

  -- 25 a direct write that leaves a gap (as the table owner, e.g. the SQL editor) is refused at the check
  execute 'reset role';
  begin
    update public.grade_boundaries set max_percent = 64 where organization_id = v_org and section_id is null and grade = 'B';
    execute 'set constraints all immediate';
    v_log := v_log || E'\nFAIL 25 a gap left by a direct write passed the deferred check';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' and sqlerrm like 'A grade scale must cover 0 to 100 exactly%' then 'PASS' else 'FAIL' end
          || ' 25 the deferred check refuses a direct write that leaves a gap [' || sqlerrm || ']';
  end;
  execute 'set constraints all deferred';

  -- 26 a direct whole-set replace (delete, then insert, one transaction) passes, because the check waits for the end
  begin
    delete from public.grade_boundaries where section_id = v_nursery;
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent, is_pass)
    values (v_org, v_nursery, 'P', 50, 100, true), (v_org, v_nursery, 'F', 0, 49, false);
    execute 'set constraints all immediate';
    execute 'set constraints all deferred';
    v_log := v_log || E'\nPASS 26 a delete-then-insert of a whole set passes the deferred check';
  exception when others then
    v_log := v_log || E'\nFAIL 26 a delete-then-insert of a whole set was refused [' || sqlerrm || ']';
  end;

  -- 27 the table checks: whole numbers, max <= 100, min <= max
  v_ok := true;
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent) values (v_org, v_secondary, 'X', 0.5, 1);
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '23514'; end;
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent) values (v_org, v_secondary, 'X', 0, 1.5);
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '23514'; end;
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent) values (v_org, v_secondary, 'X', 0, 101);
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '23514'; end;
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent) values (v_org, v_secondary, 'X', 5, 4);
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '23514'; end;
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent) values (v_org, v_secondary, 'X', 0);
    v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '23502'; end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 27 the table refuses decimals, max above 100, min above max and a missing max';

  -- ── legacy (pre-34) sets ──
  -- 28 a legacy incomplete set (built as the table owner, then undone): grading_problems
  --    reports it, grade_for has nothing below its lowest grade, and it can't be copied
  begin
    delete from public.grade_boundaries where section_id = v_primary;
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent, max_percent, is_pass)
    values (v_org, v_primary, 'A', 70, 100, true), (v_org, v_primary, 'B', 40, 69, true);

    perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
    execute 'set local role authenticated';
    v_txt := array_to_string(public.grading_problems(v_org, v_primary), ' | ');
    v_ok := v_txt = 'No grade boundary at 0% | Grades don''t cover 0% to 100% yet'
        and (public.grade_for(v_pry1a, 30)) is null
        and (public.grade_for(v_pry1a, 39.5)).grade = 'B';
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 28a grading_problems reports a legacy incomplete set [' || coalesce(v_txt, 'null') || ']';
    begin
      perform public.copy_section_grading(v_org, v_primary, v_nursery, false, true);
      v_log := v_log || E'\nFAIL 28b a legacy incomplete set was copied';
    exception when others then
      v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm = 'The grades in Primary don''t cover 0 to 100 yet, so they can''t be copied. Fix them first' then 'PASS' else 'FAIL' end
            || ' 28b a legacy incomplete set can''t be copied [' || sqlerrm || ']';
    end;
    -- replacing it with set_grade_scale is the way out
    perform public.set_grade_scale(v_org, v_primary, v_four);
    v_ok := cardinality(public.grading_problems(v_org, v_primary)) = 0;
    execute 'reset role';
    execute 'set constraints all immediate';
    execute 'set constraints all deferred';
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 28c set_grade_scale replaces a legacy set with a complete one';
    raise exception 'undo legacy fixture';
  exception when others then
    if sqlerrm <> 'undo legacy fixture' then
      v_log := v_log || E'\nFAIL 28 legacy case stopped early [' || sqlerrm || ']';
    end if;
  end;
  execute 'reset role';

  -- 29 the backfill (migration 34, step 2) on a pre-34 shaped table: the decimal check finds
  --    decimal starts; whole starts get max = next start - 1, top = 100, per set; a set that
  --    doesn't start at 0 is filled the same way
  create temp table legacy_grades (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null,
    section_id uuid,
    grade text not null,
    min_percent numeric(5, 2) not null,
    max_percent numeric(5, 2)
  ) on commit drop;
  insert into legacy_grades (organization_id, section_id, grade, min_percent) values
    (v_org,  null,      'A', 70), (v_org,  null,      'B', 60), (v_org,  null,      'F', 0),
    (v_org,  v_primary, 'A', 75), (v_org,  v_primary, 'C', 40),
    (v_org2, null,      'A', 70), (v_org2, null,      'B', 55.5);
  select count(*) into v_n from legacy_grades gb where gb.min_percent <> trunc(gb.min_percent);
  v_ok := v_n = 1;
  delete from legacy_grades where min_percent <> trunc(min_percent);
  update legacy_grades gb
  set max_percent = n.next_max
  from (
    select x.id,
           coalesce(lead(x.min_percent) over (partition by x.organization_id, x.section_id
                                              order by x.min_percent) - 1,
                    100) as next_max
    from legacy_grades x
  ) n
  where n.id = gb.id;
  select string_agg(case when organization_id = v_org2 then 'other ' when section_id is null then 'school ' else 'primary ' end
                    || grade || ' ' || min_percent::int || '-' || max_percent::int, ','
                    order by organization_id = v_org2, section_id nulls first, min_percent desc) into v_txt
    from legacy_grades;
  v_ok := v_ok and v_txt = 'school A 70-100,school B 60-69,school F 0-59,primary A 75-100,primary C 40-74,other A 70-100';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 29 backfill (on a temp table): decimals found; max = next start - 1, top 100, per set [' || coalesce(v_txt, 'null') || ']';

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('21_grade_scales_test', v_log);
end;
$test$;

-- ── 22_add_member_role_test.sql ──
do $test$
declare
  v_log     text := '';
  v_n       int;
  v_org     uuid;  v_claim  text;
  v_org2    uuid;  v_claim2 text;
  v_code    text;
  v_owner   public.organization_members;
  v_owner2  public.organization_members;
  v_pat_m   public.organization_members;
  v_tee_m   public.organization_members;
  v_sue_m   public.organization_members;
  v_new     public.organization_members;
  v_pat     uuid;
  v_tee     uuid;
  v_sue     uuid;
  v_bea     uuid;
  v_bea_m   uuid;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: two schools ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner2","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_owner2 := public.redeem_claim_code(v_claim2, 'Oma', 'Owner');

  -- ── setup: Test School's team ──
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_owner := public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Pat', 'Principal') returning id into v_pat;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Tee', 'Teacher')   returning id into v_tee;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Sue', 'Teacher')   returning id into v_sue;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Bea', 'Bursar')    returning id into v_bea;

  v_code := public.invite_staff(v_pat, 'principal');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_pat_m := public.redeem_claim_code(v_code);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_code := public.invite_staff(v_tee, 'teacher');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_tee_m := public.redeem_claim_code(v_code);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_code := public.invite_staff(v_sue, 'teacher');
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_sue","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_sue_m := public.redeem_claim_code(v_code);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.invite_staff(v_bea, 'bursar');
  execute 'reset role';
  select s.member_id into v_bea_m from public.staff s where s.id = v_bea;

  -- 01 the owner gives the principal a teacher role
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_new := public.add_member_role(v_pat_m.id, 'teacher');
  execute 'reset role';
  select count(*) into v_n from public.organization_members m
    where m.id = v_new.id
      and m.organization_id = v_org
      and m.clerk_user_id = 'test_principal'
      and m.role = 'teacher'
      and m.status = 'active'
      and m.claim_code is null
      and m.joined_at = v_pat_m.joined_at
      and m.invited_by = 'test_owner';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 01 owner adds a teacher role to the principal';

  -- 02 staff.member_id still points at the principal row
  select count(*) into v_n from public.staff s where s.id = v_pat and s.member_id = v_pat_m.id;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 02 staff record keeps its member_id';

  -- 03 the new role is live: the principal's teacher membership counts
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from private.my_org_ids(array['teacher']::public.member_role[]) o where o = v_org;
  execute 'reset role';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 03 the added role is active for the person';

  -- 04 a principal adds a bursar role to a teacher (within their tier)
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    v_new := public.add_member_role(v_tee_m.id, 'bursar');
    execute 'reset role';
    select count(*) into v_n from public.organization_members m
      where m.id = v_new.id and m.clerk_user_id = 'test_teacher' and m.role = 'bursar' and m.status = 'active'
        and m.invited_by = 'test_principal';
    v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 04 principal adds a bursar role';
  exception when others then
    execute 'reset role';
    v_log := v_log || E'\nFAIL 04 principal adds a bursar role [' || sqlerrm || ']';
  end;

  -- 05 a principal can't add an admin role
  perform set_config('request.jwt.claims', '{"sub":"test_principal","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_tee_m.id, 'admin');
    v_log := v_log || E'\nFAIL 05 principal added an admin role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 05 principal cannot add admin [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 06 a teacher can't add roles at all
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_sue_m.id, 'staff');
    v_log := v_log || E'\nFAIL 06 teacher added a role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06 teacher cannot add roles [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 07 someone not on the app yet (an unclaimed invite) is refused
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_bea_m, 'teacher');
    v_log := v_log || E'\nFAIL 07 added a role to an invite';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%isn''t on the app yet%' then 'PASS' else 'FAIL' end
      || ' 07 not-yet-active source refused [' || sqlerrm || ']';
  end;

  -- 08 a role they already hold is refused readably
  begin
    perform public.add_member_role(v_pat_m.id, 'teacher');
    v_log := v_log || E'\nFAIL 08 added a duplicate role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%already have the teacher role at%' then 'PASS' else 'FAIL' end
      || ' 08 duplicate role refused [' || sqlerrm || ']';
  end;

  -- 09 the same, asked from the other membership row
  begin
    perform public.add_member_role(v_new.id, 'teacher');  -- v_new is Tee's bursar row
    v_log := v_log || E'\nFAIL 09 added a duplicate role from the second row';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' then 'PASS' else 'FAIL' end || ' 09 duplicate from the other row refused [' || sqlerrm || ']';
  end;

  -- 10 owner is never added
  begin
    perform public.add_member_role(v_pat_m.id, 'owner');
    v_log := v_log || E'\nFAIL 10 added the owner role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 10 owner role refused [' || sqlerrm || ']';
  end;

  -- 11 parent and student aren't staff roles
  begin
    perform public.add_member_role(v_pat_m.id, 'parent');
    v_log := v_log || E'\nFAIL 11 added a parent role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 11 parent role refused [' || sqlerrm || ']';
  end;

  -- 12 a suspended source is refused
  update public.organization_members set status = 'suspended' where id = v_sue_m.id;
  begin
    perform public.add_member_role(v_sue_m.id, 'staff');
    v_log := v_log || E'\nFAIL 12 added a role to a suspended login';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%suspended%' then 'PASS' else 'FAIL' end
      || ' 12 suspended source refused [' || sqlerrm || ']';
  end;

  -- 13 a role they hold but is suspended: restore it instead
  update public.organization_members set status = 'suspended'
    where clerk_user_id = 'test_principal' and organization_id = v_org and role = 'teacher';
  begin
    perform public.add_member_role(v_pat_m.id, 'teacher');
    v_log := v_log || E'\nFAIL 13 re-added a suspended role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%Restore%' then 'PASS' else 'FAIL' end
      || ' 13 suspended existing role refused [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 14 another school's owner can't add a role at this school
  perform set_config('request.jwt.claims', '{"sub":"test_owner2","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_tee_m.id, 'staff');
    v_log := v_log || E'\nFAIL 14 another school added a role here';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 14 cross-school refused [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 15 nor can this school's owner add one at the other school
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_owner2.id, 'teacher');
    v_log := v_log || E'\nFAIL 15 added a role at another school';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 15 cross-school refused (other way) [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 16 Hamrash platform admins aren't school members, so they're refused too
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_tee_m.id, 'staff');
    v_log := v_log || E'\nFAIL 16 platform admin added a role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16 platform admin refused [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 17 the owner can add a role to their own login
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    v_new := public.add_member_role(v_owner.id, 'teacher');
    v_log := v_log || E'\n' || case when v_new.role = 'teacher' and v_new.clerk_user_id = 'test_owner' then 'PASS' else 'FAIL' end
      || ' 17 owner adds a teacher role to themselves';
  exception when others then
    v_log := v_log || E'\nFAIL 17 owner adds a teacher role to themselves [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 18 a staff member who has left is refused
  update public.staff set status = 'exited' where id = v_tee;
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.add_member_role(v_tee_m.id, 'staff');
    v_log := v_log || E'\nFAIL 18 added a role to someone who left';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' and sqlerrm like '%left the school%' then 'PASS' else 'FAIL' end
      || ' 18 exited staff refused [' || sqlerrm || ']';
  end;
  execute 'reset role';

  -- 19 anon can't call it
  execute 'set local role anon';
  begin
    perform public.add_member_role(v_tee_m.id, 'staff');
    v_log := v_log || E'\nFAIL 19 anon called add_member_role';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 19 anon has no execute [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('22_add_member_role_test', v_log);
end;
$test$;

-- ── 23_list_students_rpc_test.sql ──
do $test$
declare
  v_log     text := '';
  v_org     uuid;
  v_org2    uuid;
  v_claim   text;
  v_claim2  text;
  v_section uuid;
  v_jss1    uuid;
  v_jss2    uuid;
  v_arm_1a  uuid;
  v_arm_1b  uuid;
  v_arm_2a  uuid;
  v_session uuid;
  v_term    uuid;
  v_ada     uuid;
  v_bayo    uuid;
  v_maths   uuid;
  v_french  uuid;
  v_art     uuid;
  v_chidi   uuid;
  v_dara    uuid;
  v_ebi     uuid;
  v_femi    uuid;
  v_hope    uuid;
  v_gina    uuid;
  v_res     jsonb;
  v_row     jsonb;
  v_got     text;
  v_cursor  text;
  v_seen    text;
  v_pages   int;
  v_ok      boolean;
  v_active  public.student_status[] := array['active']::public.student_status[];
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- first names of a list_students result, in order, comma separated
  create function pg_temp.names(p jsonb) returns text language sql immutable as $f$
    select coalesce(string_agg(r ->> 'first_name', ',' order by o), '')
    from jsonb_array_elements(p -> 'rows') with ordinality as t(r, o);
  $f$;

  -- ── setup: two schools ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');
  insert into public.students (organization_id, first_name, last_name) values (v_org2, 'Bee', 'Student');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');

  insert into public.sections (organization_id, name) values (v_org, 'Secondary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_section, 'JSS 1', 1) returning id into v_jss1;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_section, 'JSS 2', 2) returning id into v_jss2;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'A') returning id into v_arm_1a;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'B') returning id into v_arm_1b;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss2, 'A') returning id into v_arm_2a;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term;
  perform public.set_current_term(v_term);

  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Ada', 'Bello', 'Teacher', 'teaching') returning id into v_ada;
  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Bayo', 'Cole', 'Teacher', 'teaching') returning id into v_bayo;

  insert into public.subjects (organization_id, name, code) values (v_org, 'Mathematics', 'MTH') returning id into v_maths;
  insert into public.subjects (organization_id, name, code) values (v_org, 'French', 'FRE') returning id into v_french;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Art', 'ART') returning id into v_art;
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_1a, v_maths);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_1b, v_maths);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_2a, v_maths);
  insert into public.arm_subjects (organization_id, arm_id, subject_id, is_compulsory) values (v_org, v_arm_1a, v_french, false);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_arm_1a, v_art);
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id)
    values (v_org, v_session, v_arm_1a, v_maths, v_ada),
           (v_org, v_session, v_arm_2a, v_maths, v_ada),
           (v_org, v_session, v_arm_1b, v_maths, v_bayo);

  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Chidi', 'Eze')    returning id into v_chidi;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Dara',  'Obi')    returning id into v_dara;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Ebi',   'Yusuf')  returning id into v_ebi;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Femi',  'Zaki')   returning id into v_femi;
  insert into public.students (organization_id, first_name, last_name, status)
    values (v_org, 'Hope', 'Zed', 'withdrawn') returning id into v_hope;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Gina',  'Zubair') returning id into v_gina;
  insert into public.student_placements (organization_id, student_id, session_id, arm_id)
    values (v_org, v_chidi, v_session, v_arm_1a), (v_org, v_dara, v_session, v_arm_1a),
           (v_org, v_hope,  v_session, v_arm_1a), (v_org, v_ebi,  v_session, v_arm_1b),
           (v_org, v_femi,  v_session, v_arm_2a);
  insert into public.student_subjects (organization_id, student_id, session_id, subject_id)
    values (v_org, v_chidi, v_session, v_french);

  -- 01 every student, in class order, one page; total and groups agree
  v_res := public.list_students(v_org);
  v_got := pg_temp.names(v_res);
  v_log := v_log || E'\n' || case when v_got = 'Chidi,Dara,Hope,Ebi,Femi,Gina'
                                    and (v_res ->> 'total')::int = 6
                                    and v_res -> 'next_cursor' = 'null'::jsonb
                                    and (select sum((g ->> 'count')::int) from jsonb_array_elements(v_res -> 'groups') g) = 6
                                  then 'PASS' else 'FAIL' end || ' 01 unfiltered, class order [' || v_got || ']';

  -- 02 name order, and the default status list the app sends
  v_got := pg_temp.names(public.list_students(v_org, p_sort => 'name'));
  v_ok := v_got = 'Chidi,Dara,Ebi,Femi,Hope,Gina';
  v_got := pg_temp.names(public.list_students(v_org, p_statuses => v_active));
  v_ok := v_ok and v_got = 'Chidi,Dara,Ebi,Femi,Gina';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 02 name sort and active-only [' || v_got || ']';

  -- 03 pages: 2 at a time in both sorts, nobody repeated or missed, same total
  for v_got in select unnest(array['class', 'name']) loop
    v_cursor := null; v_seen := ''; v_pages := 0; v_ok := true;
    loop
      v_res := public.list_students(v_org, p_sort => v_got, p_limit => 2, p_cursor => v_cursor);
      v_pages := v_pages + 1;
      v_ok := v_ok and (v_res ->> 'total')::int = 6 and jsonb_array_length(v_res -> 'rows') <= 2;
      v_seen := v_seen || case when v_seen = '' then '' else ',' end || pg_temp.names(v_res);
      v_cursor := v_res ->> 'next_cursor';
      exit when v_cursor is null or v_pages > 10;
    end loop;
    v_ok := v_ok and v_pages = 3
            and v_seen = case v_got when 'class' then 'Chidi,Dara,Hope,Ebi,Femi,Gina'
                                    else 'Chidi,Dara,Ebi,Femi,Hope,Gina' end;
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 paging by ' || v_got || ' [' || v_seen || ', ' || v_pages || ' pages]';
  end loop;

  -- 04 pages with a filter: total and rows come from the same filtered set
  v_res := public.list_students(v_org, p_subject_id => v_maths, p_statuses => v_active, p_limit => 3);
  v_ok := (v_res ->> 'total')::int = 4 and jsonb_array_length(v_res -> 'rows') = 3 and v_res ->> 'next_cursor' is not null;
  v_res := public.list_students(v_org, p_subject_id => v_maths, p_statuses => v_active, p_limit => 3,
                                p_cursor => v_res ->> 'next_cursor');
  v_ok := v_ok and (v_res ->> 'total')::int = 4 and pg_temp.names(v_res) = 'Femi' and v_res -> 'next_cursor' = 'null'::jsonb;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 04 paging keeps the filter';

  -- 05 search: name part, two words, case, admission number, literal wildcards
  v_ok := pg_temp.names(public.list_students(v_org, p_search => 'EZE')) = 'Chidi';
  v_ok := v_ok and pg_temp.names(public.list_students(v_org, p_search => '  chi   eze ')) = 'Chidi';
  v_ok := v_ok and (public.list_students(v_org, p_search => 'tst/') ->> 'total')::int = 6;
  v_ok := v_ok and (public.list_students(v_org, p_search => '%') ->> 'total')::int = 0;
  v_ok := v_ok and (public.list_students(v_org, p_search => '   ') ->> 'total')::int = 6;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 05 search';

  -- 06 section, class and arm filters; students with no arm never match them
  v_ok := pg_temp.names(public.list_students(v_org, p_class_id => v_jss1, p_statuses => v_active)) = 'Chidi,Dara,Ebi';
  v_ok := v_ok and pg_temp.names(public.list_students(v_org, p_arm_id => v_arm_1a, p_statuses => v_active)) = 'Chidi,Dara';
  v_ok := v_ok and pg_temp.names(public.list_students(v_org, p_class_id => v_jss2)) = 'Femi';
  v_ok := v_ok and (public.list_students(v_org, p_section_id => v_section, p_statuses => v_active) ->> 'total')::int = 4;
  v_ok := v_ok and (public.list_students(v_org, p_class_id => v_jss1, p_arm_id => v_arm_2a) ->> 'total')::int = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 06 section, class, arm';

  -- 07 Mathematics: compulsory everywhere, so every placed active student;
  -- each carries the teacher of THEIR arm (Ada in 1A and 2A, Bayo in 1B)
  v_res := public.list_students(v_org, p_subject_id => v_maths, p_statuses => v_active);
  select string_agg((r ->> 'first_name') || ':' || (r -> 'subject' -> 'teacher' ->> 'first_name'), ',' order by o)
    into v_got
  from jsonb_array_elements(v_res -> 'rows') with ordinality as t(r, o);
  v_log := v_log || E'\n' || case when v_got = 'Chidi:Ada,Dara:Ada,Ebi:Bayo,Femi:Ada'
                                    and (v_res ->> 'total')::int = 4
                                  then 'PASS' else 'FAIL' end || ' 07 maths with the arm''s teacher [' || coalesce(v_got, '') || ']';

  -- 08 French is optional in 1A: only the student who chose it; nobody teaches it
  v_res := public.list_students(v_org, p_subject_id => v_french);
  v_row := v_res -> 'rows' -> 0;
  v_log := v_log || E'\n' || case when pg_temp.names(v_res) = 'Chidi'
                                    and (v_row -> 'subject' ->> 'is_compulsory')::boolean = false
                                    and v_row -> 'subject' -> 'teacher' = 'null'::jsonb
                                    and v_row -> 'subject' ->> 'name' = 'French'
                                  then 'PASS' else 'FAIL' end || ' 08 optional subject, no teacher is null [' || pg_temp.names(v_res) || ']';

  -- 09 Art is compulsory in 1A only, with no teacher: both 1A students, no error
  v_res := public.list_students(v_org, p_subject_id => v_art, p_statuses => v_active);
  v_log := v_log || E'\n' || case when pg_temp.names(v_res) = 'Chidi,Dara'
                                    and not exists (select 1 from jsonb_array_elements(v_res -> 'rows') r
                                                    where r -> 'subject' -> 'teacher' <> 'null'::jsonb)
                                  then 'PASS' else 'FAIL' end || ' 09 subject nobody teaches';

  -- 10 subject with class and arm: the subject must be offered where they sit
  v_ok := pg_temp.names(public.list_students(v_org, p_subject_id => v_maths, p_class_id => v_jss2)) = 'Femi';
  v_ok := v_ok and pg_temp.names(public.list_students(v_org, p_subject_id => v_maths, p_arm_id => v_arm_1b)) = 'Ebi';
  v_ok := v_ok and (public.list_students(v_org, p_subject_id => v_french, p_arm_id => v_arm_1b) ->> 'total')::int = 0;
  v_ok := v_ok and (public.list_students(v_org, p_subject_id => gen_random_uuid()) ->> 'total')::int = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 10 subject combined with class and arm';

  -- 11 nobody is listed twice, whatever the joins
  v_res := public.list_students(v_org, p_subject_id => v_maths);
  v_log := v_log || E'\n' || case when (select count(distinct r ->> 'id') from jsonb_array_elements(v_res -> 'rows') r)
                                       = jsonb_array_length(v_res -> 'rows')
                                  then 'PASS' else 'FAIL' end || ' 11 no duplicates';

  -- 12 the arm's group counts follow the filters
  v_res := public.list_students(v_org, p_statuses => v_active);
  select (g ->> 'count')::int into v_got
  from jsonb_array_elements(v_res -> 'groups') g where (g ->> 'arm_id')::uuid = v_arm_1a;
  v_ok := v_got = '2';
  select (g ->> 'count')::int into v_got
  from jsonb_array_elements(v_res -> 'groups') g where g -> 'arm_id' = 'null'::jsonb;
  v_ok := v_ok and v_got = '1';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 12 group counts (1A has 2 active, 1 student has no arm)';

  -- 13 another session has no placements: nobody has an arm there
  v_res := public.list_students(v_org, p_session_id => gen_random_uuid(), p_statuses => v_active);
  v_log := v_log || E'\n' || case when (v_res ->> 'total')::int = 5
                                    and not exists (select 1 from jsonb_array_elements(v_res -> 'rows') r where r -> 'arm' <> 'null'::jsonb)
                                    and (public.list_students(v_org, p_session_id => gen_random_uuid(), p_arm_id => v_arm_1a) ->> 'total')::int = 0
                                  then 'PASS' else 'FAIL' end || ' 13 other session';

  -- 14 bad arguments and cursors are refused with a readable message
  v_ok := true;
  begin perform public.list_students(v_org, p_sort => 'newest'); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '22023'; end;
  begin perform public.list_students(null); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '22023'; end;
  begin perform public.list_students(v_org, p_cursor => 'not-a-cursor'); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '22023'; end;
  v_cursor := public.list_students(v_org, p_sort => 'name', p_limit => 1) ->> 'next_cursor';
  begin perform public.list_students(v_org, p_sort => 'class', p_cursor => v_cursor); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '22023'; end;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 14 bad sort, school and cursors refused';

  -- 15 school boundaries: the other school's student never shows, and the
  -- other school's list is empty for this owner
  v_ok := position('Bee' in pg_temp.names(public.list_students(v_org))) = 0;
  v_ok := v_ok and (public.list_students(v_org2) ->> 'total')::int = 0;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_stranger","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_ok := v_ok and (public.list_students(v_org) ->> 'total')::int = 0
              and public.list_students(v_org) -> 'rows' = '[]'::jsonb;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 15 other school and strangers see nothing';

  -- 16 anon can't call it
  execute 'reset role';
  execute 'set local role anon';
  begin
    perform public.list_students(v_org);
    v_log := v_log || E'\nFAIL 16 anon called list_students';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16 anon refused [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('23_list_students_rpc_test', v_log);
end;
$test$;

-- ── 24_staff_teaching_filter_test.sql ──
do $test$
declare
  v_log     text := '';
  v_org     uuid;
  v_org2    uuid;
  v_claim   text;
  v_claim2  text;
  v_section uuid;
  v_jss1    uuid;
  v_jss2    uuid;
  v_arm_1a  uuid;
  v_arm_1b  uuid;
  v_arm_2a  uuid;
  v_session uuid;
  v_term    uuid;
  v_ada     uuid;
  v_bayo    uuid;
  v_cleo    uuid;
  v_maths   uuid;
  v_art     uuid;
  v_res     jsonb;
  v_row     jsonb;
  v_got     text;
  v_seen    text;
  v_cursor  text;
  v_pages   int;
  v_ok      boolean;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  create function pg_temp.names(p jsonb) returns text language sql immutable as $f$
    select coalesce(string_agg(r ->> 'first_name', ',' order by o), '')
    from jsonb_array_elements(p -> 'rows') with ordinality as t(r, o);
  $f$;

  -- "JSS 1 A:Mathematics" for each entry of a row's teaching list
  create function pg_temp.teaching(p jsonb, p_first text) returns text language sql immutable as $f$
    select coalesce(string_agg((a ->> 'class_name') || ' ' || (a ->> 'arm_name') || ':' || (a ->> 'subject_name'), ',' order by o), 'none')
    from jsonb_array_elements(p -> 'rows') r,
         jsonb_array_elements(r -> 'teaching') with ordinality as t(a, o)
    where r ->> 'first_name' = p_first;
  $f$;

  -- ── setup ──
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');

  insert into public.sections (organization_id, name) values (v_org, 'Secondary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_section, 'JSS 1', 1) returning id into v_jss1;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_section, 'JSS 2', 2) returning id into v_jss2;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'A') returning id into v_arm_1a;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'B') returning id into v_arm_1b;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss2, 'A') returning id into v_arm_2a;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term;
  perform public.set_current_term(v_term);

  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Ada', 'Bello', 'Teacher', 'teaching') returning id into v_ada;
  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Bayo', 'Cole', 'Teacher', 'teaching') returning id into v_bayo;
  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Cleo', 'Dada', 'Teacher', 'teaching') returning id into v_cleo;

  insert into public.subjects (organization_id, name, code) values (v_org, 'Mathematics', 'MTH') returning id into v_maths;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Art', 'ART') returning id into v_art;
  insert into public.arm_subjects (organization_id, arm_id, subject_id)
    values (v_org, v_arm_1a, v_maths), (v_org, v_arm_1b, v_maths), (v_org, v_arm_2a, v_maths), (v_org, v_arm_1a, v_art);
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id)
    values (v_org, v_session, v_arm_1a, v_maths, v_ada),
           (v_org, v_session, v_arm_2a, v_maths, v_ada),
           (v_org, v_session, v_arm_1b, v_maths, v_bayo),
           (v_org, v_session, v_arm_1a, v_art,   v_bayo);

  -- 01 Mathematics: both teachers, once each; every call that worked before still works
  v_res := public.list_staff(v_org, p_subject_id => v_maths);
  v_log := v_log || E'\n' || case when pg_temp.names(v_res) = 'Ada,Bayo' and (v_res ->> 'total')::int = 2
                                    and (v_res -> 'counts' ->> 'all')::int = 2
                                  then 'PASS' else 'FAIL' end || ' 01 teachers of Mathematics [' || pg_temp.names(v_res) || ']';

  -- 02 each teacher shows the classes where they teach Mathematics, and only that
  v_got := pg_temp.teaching(v_res, 'Ada') || ' | ' || pg_temp.teaching(v_res, 'Bayo');
  v_log := v_log || E'\n' || case when v_got = 'JSS 1 A:Mathematics,JSS 2 A:Mathematics | JSS 1 B:Mathematics'
                                  then 'PASS' else 'FAIL' end || ' 02 teacher, subject and class [' || v_got || ']';

  -- 03 Art: Bayo, with the one class (not his Mathematics)
  v_res := public.list_staff(v_org, p_subject_id => v_art);
  v_log := v_log || E'\n' || case when pg_temp.names(v_res) = 'Bayo' and pg_temp.teaching(v_res, 'Bayo') = 'JSS 1 A:Art'
                                  then 'PASS' else 'FAIL' end || ' 03 a teacher of two subjects shows the one asked for';

  -- 04 class and section: the same assignment must match both
  v_ok := pg_temp.names(public.list_staff(v_org, p_class_id => v_jss2)) = 'Ada';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_subject_id => v_maths, p_class_id => v_jss2)) = 'Ada';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_subject_id => v_art, p_class_id => v_jss2)) = '';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_subject_id => v_art, p_class_id => v_jss1)) = 'Bayo';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_section_id => v_section)) = 'Ada,Bayo';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 04 class and section filters';

  -- 05 a class alone lists every subject they teach there
  v_res := public.list_staff(v_org, p_class_id => v_jss1);
  v_log := v_log || E'\n' || case when pg_temp.teaching(v_res, 'Bayo') = 'JSS 1 A:Art,JSS 1 B:Mathematics'
                                  then 'PASS' else 'FAIL' end || ' 05 class only [' || pg_temp.teaching(v_res, 'Bayo') || ']';

  -- 06 no teaching filter: nothing changes, `teaching` is null, Cleo and Olu list
  v_res := public.list_staff(v_org);
  v_log := v_log || E'\n' || case when pg_temp.names(v_res) = 'Olu,Ada,Bayo,Cleo' and (v_res ->> 'total')::int = 4
                                    and (v_res -> 'rows' -> 1 -> 'teaching') = 'null'::jsonb
                                  then 'PASS' else 'FAIL' end || ' 06 unfiltered, teaching is null [' || pg_temp.names(v_res) || ']';

  -- 07 a teacher with no assignment never matches a teaching filter
  v_ok := position('Cleo' in pg_temp.names(public.list_staff(v_org, p_subject_id => v_maths))) = 0
      and position('Cleo' in pg_temp.names(public.list_staff(v_org, p_section_id => v_section))) = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 07 no assignment, no match';

  -- 08 combines with the search, type, status and login filters
  v_ok := pg_temp.names(public.list_staff(v_org, p_subject_id => v_maths, p_search => 'bay')) = 'Bayo';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_subject_id => v_maths, p_staff_type => 'teaching')) = 'Ada,Bayo';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_subject_id => v_maths, p_login => 'on_app')) = '';
  v_ok := v_ok and pg_temp.names(public.list_staff(v_org, p_subject_id => v_maths, p_login => 'not_on_app')) = 'Ada,Bayo';
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 08 combined with the other filters';

  -- 09 pages with the filter: Ada then Bayo, same total, no repeats
  v_cursor := null; v_seen := ''; v_pages := 0; v_ok := true;
  loop
    v_res := public.list_staff(v_org, p_subject_id => v_maths, p_limit => 1, p_cursor => v_cursor);
    v_pages := v_pages + 1;
    v_ok := v_ok and (v_res ->> 'total')::int = 2;
    v_seen := v_seen || case when v_seen = '' then '' else ',' end || pg_temp.names(v_res);
    v_cursor := v_res ->> 'next_cursor';
    exit when v_cursor is null or v_pages > 5;
  end loop;
  v_log := v_log || E'\n' || case when v_ok and v_seen = 'Ada,Bayo' and v_pages = 2 then 'PASS' else 'FAIL' end
           || ' 09 paging keeps the filter [' || v_seen || ']';

  -- 10 another session, an unknown subject, or another school's subject match nobody
  v_ok := (public.list_staff(v_org, p_subject_id => v_maths, p_session_id => gen_random_uuid()) ->> 'total')::int = 0;
  v_ok := v_ok and (public.list_staff(v_org, p_subject_id => gen_random_uuid()) ->> 'total')::int = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 10 other session or subject';

  -- 11 school boundaries and privileges
  v_ok := (public.list_staff(v_org2, p_subject_id => v_maths) ->> 'total')::int = 0;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_stranger","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_ok := v_ok and (public.list_staff(v_org, p_subject_id => v_maths) ->> 'total')::int = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 11 other school and strangers see nothing';

  execute 'reset role';
  execute 'set local role anon';
  begin
    perform public.list_staff(v_org, p_subject_id => v_maths);
    v_log := v_log || E'\nFAIL 12 anon called list_staff';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 12 anon refused [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('24_staff_teaching_filter_test', v_log);
end;
$test$;

-- ── 25_move_student_to_arm_test.sql ──
do $test$
declare
  v_log     text := '';
  v_org     uuid;
  v_org2    uuid;
  v_claim   text;
  v_claim2  text;
  v_bursar_claim text;
  v_section uuid;
  v_jss1    uuid;
  v_jss2    uuid;
  v_1a      uuid;
  v_1b      uuid;
  v_1c      uuid;
  v_1d      uuid;
  v_2a      uuid;
  v_session uuid;
  v_term    uuid;
  v_maths   uuid;
  v_french  uuid;
  v_art     uuid;
  v_music   uuid;
  v_chidi   uuid;
  v_other   uuid;
  v_n       integer;
  v_arm     uuid;
  v_subjects text;
  v_ok      boolean;
begin
  begin
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('Test School', 'TST') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('Other School', 'OTH') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bee', 'Otherowner');
  insert into public.students (organization_id, first_name, last_name) values (v_org2, 'Bee', 'Student') returning id into v_other;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.organization_members (organization_id, role) values (v_org, 'bursar')
    returning claim_code into v_bursar_claim;

  insert into public.sections (organization_id, name) values (v_org, 'Secondary') returning id into v_section;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_section, 'JSS 1', 1) returning id into v_jss1;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_section, 'JSS 2', 2) returning id into v_jss2;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'A') returning id into v_1a;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'B') returning id into v_1b;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'C') returning id into v_1c;
  insert into public.class_arms (organization_id, class_id, name, is_active) values (v_org, v_jss1, 'D', false) returning id into v_1d;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss2, 'A') returning id into v_2a;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_session;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_session, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term;
  perform public.set_current_term(v_term);

  insert into public.subjects (organization_id, name, code) values (v_org, 'Mathematics', 'MTH') returning id into v_maths;
  insert into public.subjects (organization_id, name, code) values (v_org, 'French', 'FRE') returning id into v_french;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Art', 'ART') returning id into v_art;
  insert into public.subjects (organization_id, name, code) values (v_org, 'Music', 'MUS') returning id into v_music;
  insert into public.arm_subjects (organization_id, arm_id, subject_id)
    values (v_org, v_1a, v_maths), (v_org, v_1b, v_maths), (v_org, v_1c, v_maths), (v_org, v_2a, v_maths), (v_org, v_1d, v_maths);
  insert into public.arm_subjects (organization_id, arm_id, subject_id, is_compulsory)
    values (v_org, v_1a, v_french, false), (v_org, v_1b, v_french, false), (v_org, v_1a, v_art, false);
  insert into public.arm_subjects (organization_id, arm_id, subject_id) values (v_org, v_1c, v_music);

  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Chidi', 'Eze') returning id into v_chidi;
  insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_chidi, v_session, v_1a);
  insert into public.student_subjects (organization_id, student_id, session_id, subject_id)
    values (v_org, v_chidi, v_session, v_french), (v_org, v_chidi, v_session, v_art);

  -- 01 into 1B: French is optional there and stays, Art isn't offered and goes
  v_n := public.move_student_to_arm(v_chidi, v_1b);
  select arm_id into v_arm from public.student_placements where student_id = v_chidi and session_id = v_session;
  select string_agg(s.name, ',' order by s.name) into v_subjects
  from public.student_subjects ss join public.subjects s on s.id = ss.subject_id
  where ss.student_id = v_chidi and ss.session_id = v_session;
  v_log := v_log || E'\n' || case when v_n = 1 and v_arm = v_1b and v_subjects = 'French' then 'PASS' else 'FAIL' end
           || ' 01 move to 1B keeps French, drops Art [' || v_n || ', ' || coalesce(v_subjects, '') || ']';

  -- 02 into 1C: French isn't offered there, so it goes too; the move still counts
  v_n := public.move_student_to_arm(v_chidi, v_1c);
  select count(*) into v_n from public.student_subjects where student_id = v_chidi and session_id = v_session;
  select arm_id into v_arm from public.student_placements where student_id = v_chidi and session_id = v_session;
  v_log := v_log || E'\n' || case when v_n = 0 and v_arm = v_1c then 'PASS' else 'FAIL' end || ' 02 move to 1C drops the rest';

  -- 03 a student with no optional choices moves and removes nothing
  v_ok := public.move_student_to_arm(v_chidi, v_2a) = 0;
  select arm_id into v_arm from public.student_placements where student_id = v_chidi and session_id = v_session;
  v_log := v_log || E'\n' || case when v_ok and v_arm = v_2a then 'PASS' else 'FAIL' end || ' 03 plain move, nothing removed';

  -- 04 refusals: same arm, switched-off arm, another school's arm, unknown arm
  v_ok := true;
  begin perform public.move_student_to_arm(v_chidi, v_2a); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = 'P0001' and sqlerrm like 'They are already%'; end;
  begin perform public.move_student_to_arm(v_chidi, v_1d); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = 'P0001' and sqlerrm like 'That arm is switched off%'; end;
  begin perform public.move_student_to_arm(v_chidi, gen_random_uuid()); v_ok := false;
  exception when others then v_ok := v_ok and sqlstate = '42501'; end;
  select arm_id into v_arm from public.student_placements where student_id = v_chidi and session_id = v_session;
  v_ok := v_ok and v_arm = v_2a;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 04 refusals leave the placement alone';

  -- 05 a student with no placement this session has nothing to move
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Gina', 'Zubair') returning id into v_other;
  begin
    perform public.move_student_to_arm(v_other, v_1a);
    v_log := v_log || E'\nFAIL 05 moved a student with no placement';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = 'P0001' then 'PASS' else 'FAIL' end || ' 05 not in a class yet [' || sqlerrm || ']';
  end;

  -- 06 a student of another school is not found
  select id into v_other from public.students where organization_id = v_org2 limit 1;
  begin
    perform public.move_student_to_arm(v_other, v_1a);
    v_log := v_log || E'\nFAIL 06 moved another school''s student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06 other school refused';
  end;

  -- 07 a bursar can look but not move
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bursar_claim);
  begin
    perform public.move_student_to_arm(v_chidi, v_1a);
    v_log := v_log || E'\nFAIL 07 a bursar moved a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate in ('42501', 'P0001') then 'PASS' else 'FAIL' end || ' 07 bursar refused [' || sqlerrm || ']';
  end;
  execute 'reset role';
  select arm_id into v_arm from public.student_placements where student_id = v_chidi and session_id = v_session;
  v_log := v_log || E'\n' || case when v_arm = v_2a then 'PASS' else 'FAIL' end || ' 07b the bursar changed nothing';

  -- 08 a stranger and anon
  perform set_config('request.jwt.claims', '{"sub":"test_stranger","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.move_student_to_arm(v_chidi, v_1a);
    v_log := v_log || E'\nFAIL 08 a stranger moved a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08 stranger refused';
  end;
  execute 'reset role';
  execute 'set local role anon';
  begin
    perform public.move_student_to_arm(v_chidi, v_1a);
    v_log := v_log || E'\nFAIL 09 anon called move_student_to_arm';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 09 anon refused [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('25_move_student_to_arm_test', v_log);
end;
$test$;

select test,
       (length(report) - length(replace(report, 'PASS ', ''))) / 5 as passed,
       (length(report) - length(replace(report, 'FAIL ', ''))) / 5
         + (length(report) - length(replace(report, 'ERROR ', ''))) / 6 as failed,
       report
from test_reports order by test;
